      "content": "{\n  \"name\": \"@michengai/dsh-skills-manager\",\n  \"version\": \"1.2.21\",\n  \"description\": \"DSH Skills Manager — 在 DeepSeek Harness 中统一加载并安全管理本机 Agent Skills · Load and safely manage local Agent Skills in DSH\",\n  \"license\": \"Apache-2.0\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/MichengAI/dsh-skills-manager.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/MichengAI/dsh-skills-manager/issues\"\n  },\n  \"homepage\": \"https://github.com/MichengAI/dsh-skills-manager#readme\",\n  \"type\": \"module\",\n  \"packageManager\": \"pnpm@11.22.0\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\",\n    \"./locale/*.json\": \"./locale/*.json\"\n  },\n  \"files\": [\n    \"locale\",\n    \"lib\",\n    \"assets\",\n    \"cordis.patch.yml\",\n    \"CHANGELOG.md\",\n    \"CHANGELOG.zh-CN.md\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-primitives\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"scripts\": {\n    \"build\": \"node scripts/build.mjs\",\n    \"test\": \"node scripts/check-committed-lib.mjs && npm run typecheck && npm run build && node test/build-test.mjs && node test/api-base.test.mjs && node test/route-lifecycle.test.mjs && node test/repositories.test.mjs && node test/repository-install-targets.test.mjs && node test/workspace-target.test.mjs && node test/workspace-routes.test.mjs && node test/workspace-list.test.mjs && node test/destination-picker.test.mjs && node test/workspace-project-page.test.mjs && node test/repository-ui.test.mjs && node test/catalog-skill.test.mjs && node test/skills-sh-catalog.test.mjs && node test/clawhub-catalog.test.mjs && node --test test/catalog-state.test.mjs test/catalog-lifecycle.test.mjs && node test/theme-select.test.mjs && node --test test/antd-theme.browser.test.mjs && node test/host-fallback.test.mjs && node test/repository-routes.test.mjs && node test/core-test.mjs && node test/root-path.test.mjs && node test/custom-sources.test.mjs && node test/disabled-external-native.test.mjs && node test/categories.test.mjs && node test/categories-ui.test.mjs && node --experimental-strip-types --test test/settings-nav-icon.test.mjs && node test/readonly-discovery.test.mjs && node test/project-root-skills.test.mjs && node test/project-sources.test.mjs && node test/locale-test.mjs && node --test test/plugin-updater.test.mjs && node test/plugin-update-locale.test.mjs && node test/client-scope.test.mjs && node test/compatibility-options-test.mjs && node test/sidebar-entry.test.mjs && node --test test/sidebar-entry-lifecycle.test.mjs test/plugin-update-visibility.test.mjs && node test/online-update.test.mjs\",\n    \"verify\": \"node scripts/sync-hosts.mjs && npm test && npm run pack:check && node test/pack-test.mjs\",\n    \"pack:check\": \"npm pack --dry-run --json\",\n    \"prepack\": \"npm run typecheck && npm run build\",\n    \"prepublishOnly\": \"npm run verify\",\n    \"test:compat\": \"node scripts/test-host-compatibility.mjs\",\n    \"typecheck\": \"tsc --noEmit\"\n  },\n  \"publishConfig\": {\n    \"registry\": \"https://registry.npmjs.org/\",\n    \"access\": \"public\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \">=4.0.1 <5.0.0\",\n    \"@deepseek-ai/dsh-client-locale\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-host-webserver\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-session\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-skill\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-tools\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-web-app\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.5\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-scope\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-session\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-skill\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-tools\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-web-app\": \"0.2.1-rc.3\",\n    \"@types/node\": \"22.20.4\",\n    \"@types/react\": \"18.3.31\",\n    \"@types/react-dom\": \"18.3.7\",\n    \"esbuild\": \"0.25.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"18.3.1\",\n    \"typescript\": \"5.9.3\",\n    \"@deepseek-ai/schemastery\": \"3.18.5\"\n  },\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\",\n    \"dsh\": \">=0.2.0-rc.1 <0.3.0-0\"\n  },\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"skill\",\n    \"skills\",\n    \"cordis\"\n  ],\n  \"dependencies\": {\n    \"fflate\": \"0.8.3\"\n  },\n  \"icon\": \"assets/icon.svg\"\n}\n"
