      "path": "src/index.ts",
      "content": "import type { IncomingMessage, ServerResponse } from \"node:http\";\nimport type { HostContext, ProviderControl, Agent } from \"./host-types.js\";\nimport type { Log, Serialize, CreateInput, UploadInput, SkillRequest, RepositoryInput, ScopeOptions, SkillRoot, OperationError, RootView, Diagnostic } from \"./types.js\";\nimport type { ProviderCandidate } from \"./core.js\";\nimport type { CodedError } from \"./types.js\";\n// dsh-skills-manager host half：设置面板的 HTTP 后端（webServer prefix 路由）\n// - host 路由仅依赖 node: 内置与本地 core.js；ZIP 解压封装在 core\n// - 路由：状态、启停、详情、创建、导入、回收站\n// - 全部接口先校验 DSH Web 信任的 Host；写接口再校验请求标记与 JSON\n// - 所有来源的启停只写 manager 状态，不改原始 Skill 文件\n// - $DSH_HOME\\skills 与活动项目 .dsh/skills 可创建、回收与恢复；Agent 来源文件保持只读\n\nimport { appendFile, rename, rm, stat, realpath } from \"node:fs/promises\";\nimport {\n  state,\n  setSkillEnabled,\n  setSourceEnabled,\n  createCategory,\n  renameCategory,\n  deleteCategory,\n  assignSkillCategory,\n  moveSkillInCategory,\n  setCategoryEnabled,\n  importSkill,\n  importUploadedSkill,\n  browseDirectories,\n  createSkill,\n  skillDetail,\n  listProviderCandidates,\n  getProviderSkill,\n  userRoots,\n  setRootPath,\n  addCustomSources,\n  updateCustomSource,\n  removeCustomSource,\n  scanCustomSourceCandidates,\n  projectRoots,\n  resolveWorkspaceTarget,\n  listWorkspaces,\n  workspaceSkills,\n  logPath,\n  getSidebarEntry,\n  setSidebarEntry,\n  getOnlineUpdate,\n  setOnlineUpdate,\n} from \"./core.js\";\nimport { registerPluginUpdater } from \"./plugin-updater.js\";\nimport { createRepositoryManager } from \"./repositories.js\";\nimport { installationSourceKey } from \"./repository-updates.js\";\nimport { listClawHub, searchClawHub } from \"./clawhub-catalog.js\";\nimport { searchSkillsSh } from \"./skills-sh-catalog.js\";\nimport { loadCatalogPackage, readCatalogSkill } from \"./catalog-skill.js\";\n\nconst name = \"skills-manager\";\nconst inject = [\"webServer\", \"skills\", \"tools\", \"sessions\"];\nconst CLIENT_MARKER_HEADER = \"x-dsh-skills-manager\";\nconst MAX_LOG_BYTES = 1 << 20;\n// 文件夹上传允许 64 MiB 原始内容；Base64 会膨胀约 1/3，再为最多 1000 条路径预留余量。\nconst MAX_UPLOAD_BODY_BYTES = 88 << 20;\n\nfunction makeLog(): Log {\n  const file = logPath();\n  let queue = Promise.resolve();\n  return async (event, detail) => {\n    queue = queue.then(async () => {\n      try {\n        const current = await stat(file).catch(() => null);\n        if (current && current.size >= MAX_LOG_BYTES) {\n          await rm(`${file}.1`, { force: true });\n          await rename(file, `${file}.1`);\n        }\n        await appendFile(file, `${JSON.stringify({ ts: new Date().toISOString(), event, detail })}\\n`, \"utf8\");\n      } catch {\n        /* 日志失败不阻塞主流程 */\n      }\n    });\n    await queue;\n  };\n}\n\nfunction readBody(req: IncomingMessage, limit = 1 << 20) {\n  return new Promise<RequestBody>((resolve, reject) => {\n    let size = 0;\n    let settled = false;\n    const chunks: Buffer[] = [];\n    const fail = (error: Error) => {\n      if (settled) return;\n      settled = true;\n      reject(error);\n    };\n    req.on(\"data\", (c) => {\n      if (settled) return;\n      size += c.length;\n      if (size > limit) {\n        const error: CodedError = new Error(\"body too large\");\n        error.statusCode = 413;\n        error.code = \"error.proto.bodyTooLarge\";\n        fail(error);\n        req.resume();\n        return;\n      }\n      chunks.push(c);\n    });\n    req.on(\"end\", () => {\n      if (settled) return;\n      try {\n        const raw = Buffer.concat(chunks).toString(\"utf8\");\n        const body: RequestBody = raw ? JSON.parse(raw) : {};\n        settled = true;\n        resolve(body);\n      } catch (caught) { const e = caught as CodedError;\n        const error: CodedError = new Error(`invalid JSON body: ${e.message}`);\n        error.statusCode = 400;\n        error.code = \"error.proto.invalidJson\";\n        fail(error);\n      }\n    });\n    req.on(\"error\", fail);\n  });\n}\n\n/** 将裸 `host[:port]` authority 解析为 URL；非法形态返回 undefined。 */\nfunction parseAuthority(authority: string) {\n  try {\n    return new URL(`http://${authority}`);\n  } catch {\n    return undefined;\n  }\n}\n\n/**\n * 返回 authority 的规范形态。用 http/https 双重解析保留显式的 :80 / :443，\n * 避免默认端口被 WHATWG URL 自动剥离后意外扩大为任意端口授权。\n */\nfunction canonicalAuthority(authority: string, parsed: URL) {\n  const port = parsed.port !== \"\" ? parsed.port : new URL(`https://${authority}`).port;\n  return port === \"\" ? parsed.hostname : `${parsed.hostname}:${port}`;\n}\n\n/** 只接受纯净、规范的 host[:port]，拒绝路径、userinfo、空白和非规范端口。 */\nfunction isCanonicalAuthority(authority: string, parsed: URL) {\n  return canonicalAuthority(authority, parsed) === authority.toLowerCase();\n}\n\n/** 与 DSH `/api` 信任栅栏一致：localhost、IPv6 loopback 或 IPv4 127/8。 */\nfunction isLoopbackHostname(hostname: string) {\n  if (hostname === \"localhost\" || hostname === \"[::1]\") return true;\n  const parts = hostname.split(\".\");\n  return parts.length === 4 && parts[0] === \"127\" && parts.every((part) => /^\\d{1,3}$/.test(part) && Number(part) <= 255);\n}\n\n/** 带端口的 trustedHosts 条目精确匹配；不带端口的条目匹配同主机的任意端口。 */\nfunction isTrustedAuthority(hostUrl: URL, trustedHosts: string[]) {\n  return trustedHosts.some((entry) => {\n    if (typeof entry !== \"string\") return false;\n    const entryUrl = parseAuthority(entry);\n    if (!entryUrl || !isCanonicalAuthority(entry, entryUrl)) return false;\n    return canonicalAuthority(entry, entryUrl) === entryUrl.hostname\n      ? entryUrl.hostname === hostUrl.hostname\n      : entryUrl.host === hostUrl.host;\n  });\n}\n\n/**\n * 复用 DSH Web runtime 的 trustedHosts（LAN IP + `--trusted-host`），同时\n * 保留 loopback 默认值；未知 Host、跨站 Fetch 或异源 Origin 继续拒绝。\n */\nfunction validateRequestOrigin(req: IncomingMessage, trustedHosts: string[] = []) {\n  const host = typeof req.headers.host === \"string\" ? req.headers.host : \"\";\n  const hostUrl = parseAuthority(host);\n  if (!hostUrl || !isCanonicalAuthority(host, hostUrl)) {\n    return { statusCode: 403, code: \"error.proto.forbiddenHost\", error: \"forbidden host\" };\n  }\n  if (!isLoopbackHostname(hostUrl.hostname) && !isTrustedAuthority(hostUrl, trustedHosts)) {\n    return { statusCode: 403, code: \"error.proto.forbiddenHost\", error: \"forbidden host\" };\n  }\n  if (req.headers[\"sec-fetch-site\"] === \"cross-site\") {\n    return { statusCode: 403, code: \"error.proto.forbiddenHost\", error: \"forbidden host\" };\n  }\n  const origin = req.headers.origin;\n  if (typeof origin === \"string\") {\n    try {\n      if (new URL(origin).host !== hostUrl.host) {\n        return { statusCode: 403, code: \"error.proto.forbiddenHost\", error: \"forbidden host\" };\n      }\n    } catch {\n      return { statusCode: 403, code: \"error.proto.forbiddenHost\", error: \"forbidden host\" };\n    }\n  }\n  return null;\n}\n\n/** 写接口额外要求自定义头与 JSON；自定义头迫使跨站 fetch 预检，且本接口不回 CORS。 */\nfunction validateMutationRequest(req: IncomingMessage, trustedHosts: string[]) {\n  const hostError = validateRequestOrigin(req, trustedHosts);\n  if (hostError) return hostError;\n  if (req.headers[CLIENT_MARKER_HEADER] !== \"1\") return { statusCode: 403, code: \"error.proto.forbidden\", error: \"forbidden mutation request\" };\n  const contentType = String(req.headers[\"content-type\"] || \"\").split(\";\", 1)[0].trim().toLowerCase();\n  if (contentType !== \"application/json\") return { statusCode: 415, code: \"error.proto.contentType\", error: \"content-type must be application/json\" };\n  return null;\n}\n\nfunction json(res: ServerResponse, code: number, payload: unknown, headOnly = false) {\n  if (!res || res.writableEnded || res.destroyed) return;\n  res.once(\"error\", () => {});\n  try {\n    const body = JSON.stringify(payload);\n    res.writeHead(code, {\n      \"content-type\": \"application/json; charset=utf-8\",\n      \"content-length\": Buffer.byteLength(body),\n    });\n    // HEAD 按 RFC 语义返回与实体一致的 content-length，但不输出 body。\n    res.end(headOnly ? undefined : body);\n  } catch {\n    /* 客户端已断开 */\n  }\n}\n\n/** 成功统一包成 { ok: true, data }；核心返回 { ok:false, error } 时透传为 400。 */\nfunction run(res: ServerResponse, task: () => unknown, afterSuccess?: () => void, headOnly = false) {\n  return Promise.resolve().then(task).then((r) => {\n    if (r && typeof r === \"object\" && \"ok\" in r && r.ok === false) json(res, 400, r, headOnly);\n    else {\n      try {\n        if (afterSuccess) afterSuccess();\n      } catch {\n        /* 目录刷新失败不影响已完成的文件操作 */\n      }\n      json(res, 200, { ok: true, data: r }, headOnly);\n    }\n  }).catch((e) => {\n    try {\n      json(res, Number.isInteger(e && e.statusCode) ? e.statusCode! : 500, {\n        ok: false,\n        ...(e && typeof e.code === \"string\" ? { code: e.code } : {}),\n        ...(e && e.params && typeof e.params === \"object\" && !Array.isArray(e.params) ? { params: e.params } : {}),\n        error: String(e && e.message ? e.message : e),\n      }, headOnly);\n    } catch {\n      /* response already closed */\n    }\n  });\n}\n\n/** 文件写入后刷新宿主技能目录，并通知 Web 端重拉 `/` 菜单缓存。 */\nfunction notifyChatCatalog(ctx: HostContext, invalidateSkills?: () => void) {\n  try {\n    if (typeof invalidateSkills === \"function\") invalidateSkills();\n  } catch {\n    /* 目录缓存失效失败不影响已完成的文件操作 */\n  }\n  try {\n    if (typeof ctx.emit === \"function\") ctx.emit(\"commands/change\");\n  } catch {\n    /* 命令目录刷新失败不影响已完成的文件操作 */\n  }\n  try {\n    const sessions = typeof ctx.get === \"function\" ? ctx.get(\"sessions\") : undefined;\n    const list = sessions && typeof sessions.list === \"function\" ? sessions.list() : [];\n    for (const session of list) {\n      const id = session && (session.id ?? session.header?.id);\n      const preset = session && session.header && typeof session.header.agentPreset === \"string\"\n        ? session.header.agentPreset\n        : undefined;\n      if (id == null || !preset || typeof ctx.emit !== \"function\") continue;\n      // Web `/` 技能菜单缓存在 dsh-client-ui-skill，只在 agent-preset/selected 时失效；\n      // skills/change 未进入官方转发白名单，只能借用这条已转发事件。\n      ctx.emit(\"agent-preset/selected\", id, preset);\n    }\n  } catch {\n    /* 斜杠菜单刷新失败不影响已完成的文件操作 */\n  }\n}\n\n/**\n * 读取宿主登记的工作区路径。服务缺失、方法缺失或抛错都返回 undefined，\n * 由 resolveWorkspaceTarget 统一拒绝写项目，用户目录写入不受影响。\n */\nfunction registeredWorkspacePaths(ctx: HostContext): string[] | undefined {\n  try {\n    const registry = typeof ctx.get === \"function\" ? ctx.get(\"workspaceRegistry\") : undefined;\n    if (!registry || typeof registry.list !== \"function\") return undefined;\n    return [...registry.list()].flatMap((item) => {\n      const path = item?.path ?? item?.cwd;\n      return typeof path === \"string\" && path.trim() ? [path.trim()] : [];\n    });\n  } catch {\n    return undefined;\n  }\n}\n\n/** 仅从客户端当前选中的已知 Session 解析工作目录；缺失或失效时不回退其他会话。 */\nfunction activeSessionCwds(ctx: HostContext, sessionId: unknown) {\n  if (typeof sessionId !== \"string\" || !sessionId.trim()) return [];\n  const sessions = ctx.sessions || (typeof ctx.get === \"function\" ? ctx.get(\"sessions\") : undefined);\n  if (!sessions) return [];\n  const session = typeof sessions.get === \"function\" ? sessions.get(sessionId) :\n    (typeof sessions.list === \"function\" ? sessions.list() : []).find((item) => (item.id ?? item.header?.id) === sessionId);\n  const cwd = session?.header?.cwd;\n  return typeof cwd === \"string\" && cwd.trim() ? [cwd.trim()] : [];\n}\n\nfunction externalSkillProvider(control: ProviderControl, invalidators: Set<() => void>) {\n  invalidators.add(control.invalidate);\n  if (control.signal && typeof control.signal.addEventListener === \"function\") {\n    control.signal.addEventListener(\"abort\", () => {\n      invalidators.delete(control.invalidate);\n    }, { once: true });\n  }\n  return {\n    name: \"dsh-skills-manager-external\",\n    list: async (options?: ScopeOptions) => listProviderCandidates(options),\n    get: async (candidate: ProviderCandidate, options?: ScopeOptions) => getProviderSkill(candidate, options),\n  };\n}\n\n/**\n * Agent presets register their filesystem provider in a nearer, preset-scoped\n * skill layer. Register the manager policy once more in each live agent's own\n * layer so disabled shared skills cannot fall through to that native provider.\n */\nfunction registerAgentSkillProviders(ctx: HostContext, invalidators: Set<() => void>) {\n  if (typeof ctx.on !== \"function\") return () => {};\n  const registrations = new Map<string, () => void>();\n\n  const install = (agent: Agent) => {\n    if (!agent || registrations.has(agent.id)) return;\n    const agentCtx = agent.ctx;\n    const skills = agentCtx && typeof agentCtx.get === \"function\"\n      ? agentCtx.get(\"skills\")\n      : agentCtx && agentCtx.skills;\n    if (!skills || typeof skills.registerProvider !== \"function\") return;\n    const dispose = skills.registerProvider((control) => externalSkillProvider(control, invalidators));\n    registrations.set(agent.id, dispose);\n  };\n\n  const uninstall = (agent: Agent) => {\n    if (!agent) return;\n    const dispose = registrations.get(agent.id);\n    registrations.delete(agent.id);\n    if (typeof dispose === \"function\") dispose();\n  };\n\n  const stopCreated = ctx.on(\"agent/created\", ({ agent }) => install(agent));\n  const stopDisposed = ctx.on(\"agent/disposed\", ({ agent }) => uninstall(agent));\n  const agents = typeof ctx.get === \"function\" ? ctx.get(\"agents\") : undefined;\n  if (agents && typeof agents.list === \"function\") {\n    for (const agent of agents.list()) install(agent);\n  }\n\n  return () => {\n    if (typeof stopCreated === \"function\") stopCreated();\n    if (typeof stopDisposed === \"function\") stopDisposed();\n    for (const dispose of registrations.values()) {\n      if (typeof dispose === \"function\") dispose();\n    }\n    registrations.clear();\n  };\n}\n\nexport interface PluginConfig {\n  updater?: boolean;\n  onlineUpdate?: boolean;\n}\n\nfunction apply(ctx: HostContext, config?: PluginConfig) {\n  const hostDisabled = config?.updater === false || config?.onlineUpdate === false;\n  const isUpdateEnabled = async () => {\n    if (hostDisabled) return false;\n    return await getOnlineUpdate();\n  };\n\n  ctx.effect(() => registerPluginUpdater(ctx, {\n    endpoint: \"/api/michengai/dsh-skills-manager/update\",\n    packageName: \"@michengai/dsh-skills-manager\",\n    manifestUrl: new URL(\"../package.json\", import.meta.url),\n    isEnabled: isUpdateEnabled,\n  }), \"skills-manager: plugin updater\");\n  const log = makeLog();\n  const repositories = createRepositoryManager({ log, registeredWorkspaces: () => registeredWorkspacePaths(ctx) });\n  const getTrustedHosts = () => {\n    try {\n      const rawCtx = ctx as unknown as Record<string, unknown>;\n      // Cordis context proxy throws \"cannot get property X without inject\" on rawCtx.webRuntime or rawCtx.get\n      // Check root properties or safe get without throwing\n      const root = (rawCtx.root || rawCtx) as Record<string, unknown>;\n      const candidate = root.webRuntime || root.webStartup;\n      if (candidate && typeof candidate === \"object\" && Array.isArray((candidate as { trustedHosts?: unknown }).trustedHosts)) {\n        return (candidate as { trustedHosts: string[] }).trustedHosts;\n      }\n    } catch {\n      // ignore\n    }\n    return [];\n  };\n  // 目录可被 roots.json 改写，来源定义必须在每次请求时重新读取，不能缓存在启动时。\n  const findUserRoot = (key: string) => userRoots().find((root) => root.key === key);\n\n  const providerInvalidators = new Set<() => void>();\n  const invalidateSkills = () => {\n    for (const invalidate of providerInvalidators) invalidate();\n  };\n  const afterWrite = () => notifyChatCatalog(ctx, invalidateSkills);\n  let mutationQueue: Promise<unknown> = Promise.resolve();\n  const enqueueMutation: Serialize = (task) => {\n    const queued = mutationQueue.then(task, task);\n    mutationQueue = queued.catch(() => undefined);\n    return queued;\n  };\n  ctx.effect(() => ctx.skills.registerProvider((control) => externalSkillProvider(control, providerInvalidators)), \"skills-manager global external skills provider\");\n  ctx.effect(() => registerAgentSkillProviders(ctx, providerInvalidators), \"skills-manager agent-scoped external skills providers\");\n\n  if (ctx.tools && typeof ctx.tools.register === \"function\") {\n    ctx.effect(() => ctx.tools!.register({\n      name: \"create_skill\",\n      description: \"Create a new local DSH skill in DSH_HOME/skills. Use only when the user explicitly asks to create or save a reusable skill.\",\n      parameters: {\n        type: \"object\",\n        properties: {\n          name: { type: \"string\", description: \"Skill name; it will be normalized to kebab-case.\" },\n          description: { type: \"string\", description: \"A concise routing description for when to use the skill.\" },\n          body: { type: \"string\", description: \"Markdown instructions that form the skill body.\" },\n        },\n        required: [\"name\", \"description\", \"body\"],\n        additionalProperties: false,\n      },\n      output: {\n        schema: { type: \"object\" },\n        render: (_args, value) => [{ type: \"text\", text: value && value.ok === false ? `Skill creation failed${typeof value.code === \"string\" ? ` (${value.code})` : \"\"}.` : `Created DSH skill ${value.name} at ${value.path}` }],\n      },\n      async execute(args) {\n        return enqueueMutation(async () => {\n          const result = await createSkill(args, log);\n          if (!result || result.ok !== false) afterWrite();\n          return result;\n        });\n      },\n      presentCall(args) {\n        return { card: \"generic\", title: \"Create DSH skill\", kind: \"edit\", rawInput: args && args.name ? String(args.name) : undefined };\n      },\n    }), \"skills-manager create_skill tool\");\n    if (typeof ctx.on === \"function\") ctx.on(\"tools/pre-execute\", (exec, next) => {\n      if (exec && exec.name === \"create_skill\") return Promise.resolve({ kind: \"ask\", reason: \"Create a new skill under DSH_HOME/skills\" });\n      return next();\n    });\n  }\n\n  // Cordis can construct a plain function apply(), so its returned disposer\n  // is not collected. Own the route explicitly for restart and startup failure.\n  ctx.effect(() => ctx.webServer.register({\n    kind: \"prefix\",\n    path: \"/api/michengai/dsh-skills-manager\",\n    handler: async (req, res) => {\n      const u = new URL(req.url!, \"http://localhost\");\n      const path = u.pathname.replace(/\\/+$/, \"\");\n      const sessionId = req.headers[\"x-dsh-skills-session\"];\n      const projectOptions = () => ({ projectCwds: activeSessionCwds(ctx, sessionId) });\n      /** 请求体带 workspace 时只经登记列表解析；字段存在但无效也拒绝，不静默回退到用户目录。 */\n      const workspaceTarget = async (body: RequestBody) => {\n        if (body.workspace === undefined) return null;\n        return resolveWorkspaceTarget(body.workspace, registeredWorkspacePaths(ctx));\n      };\n      /** 项目页操作带 workspace：先按登记路径校验，再只在该项目的来源里解析，不依赖当前会话。 */\n      const workspaceScope = async (body: RequestBody): Promise<{ projectCwds: string[] } | OperationError | null> => {\n        const target = await workspaceTarget(body);\n        if (!target) return null;\n        if (\"ok\" in target && target.ok === false) return target;\n        return { projectCwds: (target as { root: SkillRoot }).root.workspaceCwds ?? [] };\n      };\n      const scopedOptions = (scope: { projectCwds: string[] } | null) => scope ?? projectOptions();\n      const requestRoot = async (key: string, cwds?: string[]) => cwds ? (await projectRoots(cwds)).find((root) => root.key === key) : findUserRoot(key) || (await projectRoots(projectOptions().projectCwds)).find((root) => root.key === key);\n      /** 单项操作的统一入口：有 workspace 就在其作用域内解析根，无则沿用当前会话。 */\n      const withScope = async <T>(body: RequestBody, action: (scope: { projectCwds: string[] } | null) => Promise<T>) => {\n        const scope = await workspaceScope(body);\n        if (scope && \"ok\" in scope && scope.ok === false) return scope;\n        return action(scope as { projectCwds: string[] } | null);\n      };\n      const attachSources = async <T extends { roots: RootView[]; warnings: Diagnostic[] }>(snapshot: T) => {\n        try {\n          const sources = await repositories.sources();\n          for (const root of snapshot.roots) {\n            const realRoot = await realpath(root.path).catch(() => root.path);\n            for (const skill of root.skills || []) skill.installSource = sources[installationSourceKey(realRoot, skill.name)] ?? null;\n          }\n        } catch (caught) { const error = caught as CodedError; snapshot.warnings.push({ code: \"error.repo.state\", error: error.message }); }\n        return snapshot;\n      };\n      const stateWithSources = async () => attachSources(await state(projectOptions()));\n      try {\n        const hostError = validateRequestOrigin(req, getTrustedHosts());\n        if (hostError) {\n          json(res, hostError.statusCode, { ok: false, code: hostError.code, error: hostError.error });\n          return;\n        }\n        if (req.method === \"GET\" && path === \"/api/michengai/dsh-skills-manager/state\") {\n          return run(res, stateWithSources);\n        }\n        if (req.method === \"GET\" && path === \"/api/michengai/dsh-skills-manager/sidebar-entry\") {\n          return run(res, async () => ({ enabled: await getSidebarEntry() }));\n        }\n        if (req.method === \"GET\" && path === \"/api/michengai/dsh-skills-manager/online-update\") {\n          return run(res, async () => ({ enabled: await isUpdateEnabled(), locked: hostDisabled }));\n        }\n        if ((req.method === \"GET\" || req.method === \"HEAD\") && path === \"/api/michengai/dsh-skills-manager/workspaces\") {\n          return run(res, async () => ({ items: await listWorkspaces(registeredWorkspacePaths(ctx) ?? []) }), undefined, req.method === \"HEAD\");\n        }\n        if ((req.method === \"GET\" || req.method === \"HEAD\") && path === \"/api/michengai/dsh-skills-manager/repositories\") {\n          return run(res, () => enqueueMutation(() => repositories.list()), undefined, req.method === \"HEAD\");\n        }\n        if (req.method === \"GET\" && (path === \"/api/michengai/dsh-skills-manager/clawhub/list\" || path === \"/api/michengai/dsh-skills-manager/clawhub/search\")) {\n          const searching = path.endsWith(\"/search\");\n          const allowed = searching ? [\"q\", \"limit\"] : [\"limit\", \"cursor\", \"sort\"];\n          if ([...u.searchParams.keys()].some(key => !allowed.includes(key) || u.searchParams.getAll(key).length !== 1) || searching && !u.searchParams.has(\"q\")) {\n            json(res, 400, { ok: false, code: \"error.catalog.query\", error: \"目录查询参数无效\" });\n            return;\n          }\n          const parameter = (key: string) => u.searchParams.get(key) ?? undefined;\n          return run(res, () => searching ? searchClawHub(parameter(\"q\")!, { limit: parameter(\"limit\") }) : listClawHub({ limit: parameter(\"limit\"), sort: parameter(\"sort\"), cursor: parameter(\"cursor\") }));\n        }\n        if (req.method === \"GET\" && path === \"/api/michengai/dsh-skills-manager/skills-sh/search\") {\n          const queries = u.searchParams.getAll(\"q\");\n          if (queries.length !== 1) {\n            json(res, 400, { ok: false, code: \"error.catalog.query\", error: \"搜索词不能为空且不能超过 100 个字符\" });\n            return;\n          }\n          return run(res, () => searchSkillsSh(queries[0]));\n        }\n        if (req.method === \"HEAD\") {\n          // HEAD 复用 GET/405 的载荷计算 content-length，保持与实体一致的响应头语义。\n          if (path === \"/api/michengai/dsh-skills-manager/state\") return run(res, stateWithSources, undefined, true);\n          if (path === \"/api/michengai/dsh-skills-manager/sidebar-entry\") return run(res, async () => ({ enabled: await getSidebarEntry() }), undefined, true);\n          if (path === \"/api/michengai/dsh-skills-manager/online-update\") return run(res, async () => ({ enabled: await isUpdateEnabled(), locked: hostDisabled }), undefined, true);\n          json(res, 405, { ok: false, code: \"error.proto.method\", error: `method not allowed: ${req.method}` }, true);\n          return;\n        }\n        if (req.method !== \"POST\") {\n          json(res, 405, { ok: false, code: \"error.proto.method\", error: `method not allowed: ${req.method}` });\n          return;\n        }\n        const requestError = validateMutationRequest(req, getTrustedHosts());\n        if (requestError) {\n          json(res, requestError.statusCode, { ok: false, code: requestError.code, error: requestError.error });\n          return;\n        }\n        const body = await readBody(req, path === \"/api/michengai/dsh-skills-manager/upload\" ? MAX_UPLOAD_BODY_BYTES : undefined);\n        if (path.startsWith(\"/api/michengai/dsh-skills-manager/repositories/\") && (!body || typeof body !== \"object\" || Array.isArray(body))) {\n          json(res, 400, { ok: false, code: \"error.repo.invalid\", error: \"仓库参数必须是对象\" });\n          return;\n        }\n        if (path === \"/api/michengai/dsh-skills-manager/browse\") {\n          return run(res, () => browseDirectories(body.path));\n        }\n        // 网络只读阶段不占本地写入队列；最终文件和状态提交仍串行。\n        if (path === \"/api/michengai/dsh-skills-manager/repositories/refresh\") return run(res, () => repositories.refresh(body));\n        if (path === \"/api/michengai/dsh-skills-manager/catalog/detail\") return run(res, () => readCatalogSkill(body));\n        if (path === \"/api/michengai/dsh-skills-manager/catalog/install\") {\n          return run(res, async () => {\n            if (body.root !== undefined && body.root !== \"dsh\" && body.root !== \"agents\") throw Object.assign(new Error(\"技能安装位置无效\"), { statusCode: 400, code: \"error.repo.invalid\" });\n            if (body.workspace !== undefined && body.root !== undefined && body.root !== \"dsh\") throw Object.assign(new Error(\"工作区只能安装到项目 DSH skills\"), { statusCode: 400, code: \"error.repo.invalid\" });\n            const target = await workspaceTarget(body);\n            if (target && \"ok\" in target && target.ok === false) return target;\n            const pack = await loadCatalogPackage(body);\n            const catalogId = body.catalog === \"skillsh\" ? `skillsh:${body.source}/${body.skillId}` : `clawhub:${body.owner}/${body.slug}`;\n            return enqueueMutation(() => repositories.installCatalog(catalogId, pack, { root: body.root, ...(body.workspace === undefined ? {} : { workspace: body.workspace }) }));\n          }, afterWrite);\n        }\n        return enqueueMutation(() => {\n          switch (path) {\n            case \"/api/michengai/dsh-skills-manager/sidebar-entry\":\n              return run(res, async () => {\n                if (!body || typeof body.enabled !== \"boolean\") {\n                  throw Object.assign(new Error(\"enabled 必须是布尔值\"), { statusCode: 400, code: \"error.proto.invalidParams\" });\n                }\n                const enabled = await setSidebarEntry(body.enabled);\n                return { enabled };\n              });\n            case \"/api/michengai/dsh-skills-manager/online-update\":\n              return run(res, async () => {\n                if (!body || typeof body.enabled !== \"boolean\") {\n                  throw Object.assign(new Error(\"enabled 必须是布尔值\"), { statusCode: 400, code: \"error.proto.invalidParams\" });\n                }\n                if (hostDisabled) {\n                  throw Object.assign(new Error(\"在线更新已被宿主配置锁定禁用\"), { statusCode: 403, code: \"error.update.disabled\" });\n                }\n                const enabled = await setOnlineUpdate(body.enabled);\n                return { enabled };\n              });\n            case \"/api/michengai/dsh-skills-manager/repositories/add\":\n              return run(res, () => repositories.add(body));\n            case \"/api/michengai/dsh-skills-manager/repositories/remove\":\n              return run(res, () => repositories.remove(body));\n            case \"/api/michengai/dsh-skills-manager/repositories/detail\":\n              return run(res, () => repositories.detail(body));\n            case \"/api/michengai/dsh-skills-manager/repositories/install\":\n              return run(res, () => repositories.install(body, registeredWorkspacePaths(ctx)), afterWrite);\n            case \"/api/michengai/dsh-skills-manager/repositories/uninstall\":\n              return run(res, () => repositories.uninstall(body), afterWrite);\n            case \"/api/michengai/dsh-skills-manager/repositories/preview\":\n              return run(res, () => repositories.preview(body));\n            case \"/api/michengai/dsh-skills-manager/repositories/update\":\n              return run(res, () => repositories.update(body), afterWrite);\n            case \"/api/michengai/dsh-skills-manager/repositories/rollback\":\n              return run(res, () => repositories.rollback(body), afterWrite);\n            case \"/api/michengai/dsh-skills-manager/workspace-skills\":\n              return run(res, async () => {\n                const snapshot = await workspaceSkills(body.workspace, registeredWorkspacePaths(ctx));\n                return \"roots\" in snapshot ? attachSources(snapshot) : snapshot;\n              });\n            case \"/api/michengai/dsh-skills-manager/enable\":\n              return run(res, () => withScope(body, async (scope) => setSkillEnabled(await requestRoot(String(body.root || \"dsh\"), scope?.projectCwds), String(body.name || \"\"), true, log)), afterWrite);\n            case \"/api/michengai/dsh-skills-manager/disable\":\n              return run(res, () => withScope(body, async (scope) => setSkillEnabled(await requestRoot(String(body.root || \"dsh\"), scope?.projectCwds), String(body.name || \"\"), false, log)), afterWrite);\n            case \"/api/michengai/dsh-skills-manager/source-enable\":\n              return run(res, () => withScope(body, (scope) => setSourceEnabled(String(body.root || \"\"), true, log, scopedOptions(scope))), afterWrite);\n            case \"/api/michengai/dsh-skills-manager/source-disable\":\n              return run(res, () => withScope(body, (scope) => setSourceEnabled(String(body.root || \"\"), false, log, scopedOptions(scope))), afterWrite);\n            case \"/api/michengai/dsh-skills-manager/root-path\":\n              // path: null / \"\" 表示恢复默认目录；只改读取位置，不移动任何文件。\n              return run(res, () => setRootPath(String(body.key || \"\"), body.path === undefined ? null : body.path), afterWrite);\n            case \"/api/michengai/dsh-skills-manager/custom-source-add\":\n              // sources 支持批量：扫描结果可以一次登记多个来源；单条时直接读 label/path。\n              return run(res, () => addCustomSources(Array.isArray(body.sources) ? body.sources : body), afterWrite);\n            case \"/api/michengai/dsh-skills-manager/custom-source-update\":\n              return run(res, () => updateCustomSource(String(body.id || \"\"), body), afterWrite);\n            case \"/api/michengai/dsh-skills-manager/custom-source-remove\":\n              return run(res, () => removeCustomSource(String(body.id || \"\")), afterWrite);\n            case \"/api/michengai/dsh-skills-manager/custom-source-scan\":\n              // 只读扫描，不改动任何文件，也不登记；登记由用户确认后走 add。\n              return run(res, () => scanCustomSourceCandidates(body.path));\n            case \"/api/michengai/dsh-skills-manager/category-create\":\n              return run(res, () => withScope(body, (scope) => createCategory(String(body.root || \"\"), String(body.name || \"\"), log, scopedOptions(scope))));\n            case \"/api/michengai/dsh-skills-manager/category-rename\":\n              return run(res, () => withScope(body, (scope) => renameCategory(String(body.root || \"\"), String(body.id || \"\"), String(body.name || \"\"), log, scopedOptions(scope))));\n            case \"/api/michengai/dsh-skills-manager/category-delete\":\n              return run(res, () => withScope(body, (scope) => deleteCategory(String(body.root || \"\"), String(body.id || \"\"), log, scopedOptions(scope))));\n            case \"/api/michengai/dsh-skills-manager/category-assign\":\n              return run(res, () => withScope(body, (scope) => assignSkillCategory(String(body.root || \"\"), String(body.name || \"\"), String(body.category || \"\"), log, scopedOptions(scope))));\n            case \"/api/michengai/dsh-skills-manager/category-move\":\n              return run(res, () => withScope(body, (scope) => moveSkillInCategory(String(body.root || \"\"), String(body.name || \"\"), String(body.category || \"\"), body.targetName ? String(body.targetName) : undefined, body.position === undefined ? \"before\" : String(body.position), log, scopedOptions(scope))));\n            case \"/api/michengai/dsh-skills-manager/category-enable\":\n              return run(res, () => withScope(body, (scope) => setCategoryEnabled(String(body.root || \"\"), String(body.category || \"\"), true, log, scopedOptions(scope))), afterWrite);\n            case \"/api/michengai/dsh-skills-manager/category-disable\":\n              return run(res, () => withScope(body, (scope) => setCategoryEnabled(String(body.root || \"\"), String(body.category || \"\"), false, log, scopedOptions(scope))), afterWrite);\n            case \"/api/michengai/dsh-skills-manager/delete\":\n                          return run(res, () => withScope(body, async (scope) => {\n                            const target = await workspaceTarget(body);\n                            if (target && \"ok\" in target && target.ok === false) return target;\n                            const root = target ? (target as { root: SkillRoot }).root : await requestRoot(String(body.root || \"dsh\"), scope?.projectCwds);\n                            return repositories.trashSkill(root, String(body.name || \"\"));\n                          }), afterWrite);\n            case \"/api/michengai/dsh-skills-manager/trash-restore\":\n              return run(res, () => withScope(body, (scope) => repositories.restoreTrash(String(body.id || \"\"), { ...(scope ?? {}), registeredWorkspaces: registeredWorkspacePaths(ctx) })), afterWrite);\n            case \"/api/michengai/dsh-skills-manager/trash-delete\":\n              return run(res, () => repositories.permanentlyDeleteTrash(String(body.id || \"\")));\n            case \"/api/michengai/dsh-skills-manager/detail\":\n              return run(res, () => withScope(body, (scope) => skillDetail(String(body.root || \"dsh\"), String(body.name || \"\"), scope ? { ...scope, workspaceBound: true } : projectOptions())));\n            case \"/api/michengai/dsh-skills-manager/create\":\n              return run(res, async () => {\n                const target = await workspaceTarget(body);\n                if (target && \"ok\" in target && target.ok === false) return target;\n                return createSkill(\n                  { name: body.name, description: body.description, body: body.body },\n                  log,\n                  { root: target ? (target as { root: SkillRoot }).root : await requestRoot(String(body.root || \"dsh\")) },\n                );\n              }, afterWrite);\n            case \"/api/michengai/dsh-skills-manager/import\":\n              return run(res, async () => {\n                const target = await workspaceTarget(body);\n                if (target && \"ok\" in target && target.ok === false) return target;\n                return importSkill(String(body.source || \"\"), log, {\n                  conflict: body.conflict === \"overwrite\" ? \"overwrite\" : \"skip\",\n                  dryRun: body.dryRun === true,\n                  ...(target ? { root: (target as { root: SkillRoot }).root } : body.root === \"agents\" ? { root: await requestRoot(\"agents\") } : {}),\n                });\n              }, body.dryRun === true ? undefined : afterWrite);\n            case \"/api/michengai/dsh-skills-manager/upload\":\n              return run(res, async () => {\n                const target = await workspaceTarget(body);\n                if (target && \"ok\" in target && target.ok === false) return target;\n                return importUploadedSkill({ name: body.name, entries: body.entries, zip: body.zip }, log, {\n                  conflict: body.conflict === \"overwrite\" ? \"overwrite\" : \"skip\",\n                  ...(target ? { root: (target as { root: SkillRoot }).root } : body.root === \"agents\" ? { root: await requestRoot(\"agents\") } : {}),\n                });\n              }, afterWrite);\n            default:\n              json(res, 404, { ok: false, code: \"error.proto.unknownAction\", error: `unknown action: ${path}` });\n          }\n        });\n      } catch (caught) { const e = caught as CodedError;\n        json(res, Number.isInteger(e && e.statusCode) ? e.statusCode! : 500, {\n          ok: false,\n          ...(e && typeof e.code === \"string\" ? { code: e.code } : {}),\n          ...(e && e.params && typeof e.params === \"object\" && !Array.isArray(e.params) ? { params: e.params } : {}),\n          error: String(e && e.message ? e.message : e),\n        });\n      }\n    },\n  }), \"skills-manager: API route\");\n}\n\nexport { activeSessionCwds, apply, inject, name, notifyChatCatalog, registerAgentSkillProviders };\n\n/** 请求体由各业务入口现有校验解析，此类型只声明路由转交的字段。 */\ntype RequestBody = CreateInput & UploadInput & SkillRequest & RepositoryInput & {root?: string; source?: string; conflict?: string; dryRun?: boolean; workspace?: unknown; enabled?: boolean; category?: string; targetName?: string; position?: \"before\" | \"after\"; catalog?: string; skillId?: string; owner?: string; slug?: string; path?: unknown; key?: string; id?: string; label?: unknown; group?: unknown; sources?: unknown[]};\n"
    },
    {
      "path": "src/core.ts",
      "content": "import type { SkillRoot, RepositoryDestination, RootInput, Diagnostic, OperationError, CodedError, Log, DiscoveredEntry, SkillEntry, ParsedSkill, Scan, ManagerState, SkillCategory, PolicyResult, Policy, SkillItem, ViewItem, RootView, SkillView, ScopeOptions, MutationOptions, RenameOptions, UploadInput, CreateInput, ImportCandidate, ImportPending, ImportConflict, ImportFailure, ImportResult } from \"./types.js\";\n// dsh-skills-manager core —— 纯 Node 技能文件管理核心（仅 ZIP 解压使用 fflate，可独立单测）\n//\n// 覆盖 DSH 用户级与活动 Session 项目级技能根：\n//   - 用户根目录：~/.dsh/skills 与常见 Agent 用户目录\n//   - 项目根目录：DSH 可创建、回收；公共 Agent 与各应用目录支持本地策略启停，源文件只读\n//   - 条目形态：<root>/<name>/SKILL.md（bundle）或 <root>/<name>.md（flat），只读来源递归发现，可写来源只扫一层；顶层目录链接只读列出\n//   - 前端展示 name、description 与启停状态，不做格式检查或自动修复\n//\n// 所有函数返回普通结果对象，业务校验失败返回 { ok: false, error, code?, params? }；\n// error 保持中文原文（兼容性红线），code 为点分小写业务错误码，params 供前端词典占位符替换；\n// 系统异常（fs ENOENT 等）透传 String(e.message)，不加 code。\n// 文件写入错误由路由返回给调用方。\n\nimport { homedir } from \"node:os\";\nimport { randomBytes } from \"node:crypto\";\nimport {\n  join,\n  basename,\n  dirname,\n  resolve,\n  relative,\n  isAbsolute,\n  sep,\n} from \"node:path\";\nimport { promises as fs, readFileSync } from \"node:fs\";\nimport { createHash, randomUUID } from \"node:crypto\";\nimport { unzipSync } from \"fflate\";\nimport {\n  discoverReadonlyEntries,\n  validDiscoveryName,\n} from \"./readonly-discovery.js\";\n\nconst KEBAB_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;\n// 项目来源集中定义，路径校验、策略身份和展示共用，避免新增目录只可见却不可加载。\n// 两种作用域共用 Agent 顺序；兼容目录紧跟主目录，不扫描项目根的普通资源目录。\nconst EXTERNAL_SOURCE_ORDER = [\n  \"ccswitch\", \"codex\", \"claude\", \"gemini\", \"opencode\", \"cursor\", \"copilot\",\n  \"windsurf\", \"windsurf-user\", \"trae\", \"trae-cn\", \"openclaw\", \"clawdbot\",\n  \"roo\", \"codebuddy\", \"workbuddy\", \"qoder\", \"qoder-cn\", \"lingma\", \"antigravity\",\n];\n// 自定义来源由用户在界面登记（roots.json 的 customSources）。key 统一带前缀，\n// 与预设来源区分开，排序排到预设外部来源之后，避免插进既有顺序里改变界面分组。\nexport const CUSTOM_SOURCE_PREFIX = \"custom:\";\nconst CUSTOM_SOURCE_ID_RE = /^custom:[a-z0-9]+(?:-[a-z0-9]+)*$/;\nconst MAX_CUSTOM_SOURCES = 32;\nconst MAX_CUSTOM_LABEL_LENGTH = 48;\n/** 扫描产品总目录时向下探索的层数（0 = 只看总目录自身的 skills）。 */\nconst MAX_SOURCE_SCAN_DEPTH = 2;\nconst MAX_SOURCE_SCAN_CANDIDATES = 40;\nexport function isCustomSourceKey(key: string) {\n  return typeof key === \"string\" && key.startsWith(CUSTOM_SOURCE_PREFIX);\n}\nfunction rankSources<T extends {key: string; native?: boolean; rank?: number; localeKey?: string}>(sources: T[], startRank: number) {\n  const order = (root: T) => EXTERNAL_SOURCE_ORDER.indexOf(root.key);\n  const external = sources.filter((root) => !root.native);\n  const custom = external.filter((root) => isCustomSourceKey(root.key));\n  const preset = external.filter((root) => !isCustomSourceKey(root.key));\n  // 先逐项校验；单元素数组不会调用 sort 比较器，也不能漏过未登记来源。\n  for (const root of preset) {\n    if (order(root) < 0) throw new Error(`技能来源未登记到 EXTERNAL_SOURCE_ORDER: ${root.key}`);\n  }\n  preset.sort((a, b) => order(a) - order(b));\n  const ranks = new Map<string, number>(preset.map((root, index) => [root.key, startRank + index * 10]));\n  // 自定义来源不参与白名单校验，按登记顺序稳定排在预设来源之后。\n  const customBase = startRank + preset.length * 10;\n  custom.forEach((root, index) => ranks.set(root.key, customBase + index * 10));\n  return sources.map((root) => ({ ...root, rank: root.native ? root.rank! : ranks.get(root.key)! }))\n    .sort((a, b) => a.rank - b.rank);\n}\nconst PROJECT_SOURCES = rankSources([\n  { key: \"dsh\", directory: \".dsh\", localeKey: \"projectDsh\", label: \"Project DSH\", rank: 100, mutable: true, native: true },\n  { key: \"agents\", directory: \".agents\", localeKey: \"projectAgents\", label: \"Project Agent\", rank: 200, native: true },\n  // 保留原生项目 100/200；其余项目来源按统一 Agent 顺序生成 210–320。\n  { key: \"copilot\", directory: \".github\", localeKey: \"copilot\", label: \"Copilot\" },\n  { key: \"codex\", directory: \".codex\", localeKey: \"codex\", label: \"Codex\" },\n  { key: \"claude\", directory: \".claude\", localeKey: \"claude\", label: \"Claude Code\" },\n  { key: \"gemini\", directory: \".gemini\", localeKey: \"gemini\", label: \"Gemini\" },\n  { key: \"opencode\", directory: \".opencode\", localeKey: \"opencode\", label: \"OpenCode\" },\n  { key: \"cursor\", directory: \".cursor\", localeKey: \"cursor\", label: \"Cursor\" },\n  { key: \"windsurf\", directory: \".windsurf\", localeKey: \"windsurf\", label: \"Windsurf\" },\n  { key: \"trae\", directory: \".trae\", localeKey: \"trae\", label: \"Trae\" },\n  { key: \"trae-cn\", directory: \".trae-cn\", localeKey: \"traeCn\", label: \"Trae CN\" },\n  { key: \"roo\", directory: \".roo\", localeKey: \"roo\", label: \"Roo\" },\n  { key: \"codebuddy\", directory: \".codebuddy\", localeKey: \"codebuddy\", label: \"CodeBuddy\" },\n  { key: \"workbuddy\", directory: \".workbuddy\", localeKey: \"workbuddy\", label: \"WorkBuddy\" },\n  // Qoder CN CLI 的项目技能也写在 .qoder/skills，与国际版 Qoder 共用。\n  { key: \"qoder\", directory: \".qoder\", localeKey: \"qoder\", label: \"Qoder\" },\n  { key: \"lingma\", directory: \".lingma\", localeKey: \"lingma\", label: \"Qoder CN\" },\n], 210);\nconst PROJECT_ROOT_KEY_RE = new RegExp(\n  `^project-(?:${[...PROJECT_SOURCES]\n    .map((source) => source.key)\n    .sort((left, right) => right.length - left.length)\n    .join(\"|\")}):[a-f0-9]{16}$`,\n);\nfunction projectSourceDefinition(kind?: string) {\n  return PROJECT_SOURCES.find((source) => `project-${source.key}` === kind);\n}\nconst USER_DSH_POLICY_RANK = 399;\nconst WINDOWS_DEVICE_NAME_RE =\n  /^(con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\\..*)?$/i;\nconst MAX_SOURCE_DEPTH = 64;\nconst MAX_ENTRY_NAME_LENGTH = 128;\nconst MAX_BROWSE_ENTRIES = 500;\nconst MAX_UPLOAD_ARCHIVE_BYTES = 32 << 20;\nconst MAX_UPLOAD_ENTRY_BYTES = 32 << 20;\nconst MAX_UPLOAD_TOTAL_BYTES = 64 << 20;\nconst MAX_UPLOAD_ENTRIES = 1000;\nconst MAX_UPLOAD_PATH_LENGTH = 512;\nconst TRANSIENT_RENAME_CODES = new Set([\"EACCES\", \"EBUSY\", \"EPERM\"]);\n\n// ── 业务错误码 ────────────────────────────────────────────────────────────────\n\n/** 构造带 code/params 的业务 Error，供导入链路 throw 后透传到失败明细。 */\nfunction codedError(message: string, code: string, params?: Record<string, unknown>): CodedError {\n  const error: CodedError = new Error(message);\n  error.code = code;\n  error.params = params;\n  return error;\n}\n\n/** 把业务 Error 的 code/params 附加到失败明细；系统异常（ENOENT 等，非 error.* 前缀）保持原文。 */\nfunction attachCode<T extends Diagnostic>(item: T, error: CodedError | null | undefined): T {\n  if (error && typeof error.code === \"string\" && /^error\\./.test(error.code))\n    item.code = error.code;\n  if (error && error.params) item.params = error.params;\n  return item;\n}\n\n// ── 路径解析 ────────────────────────────────────────────────────────────────\n\nexport function resolveDshHome() {\n  return process.env.DSH_HOME || join(homedir(), \".dsh\");\n}\n\nexport function resolveAgentsHome() {\n  return process.env.DSH_AGENTS_HOME || join(homedir(), \".agents\");\n}\n\n/**\n * DSH 及常见 Agent 的用户级技能目录。\n *\n * rank 与官方 filesystem provider 的用户级优先级衔接：DSH=400、Agents=500。\n * manager provider 以 450 接管公共 Agents（仍低于 DSH），其余来源依次排在其后。\n */\nexport function userRoots(): SkillRoot[] {\n  // rank 由 rankSources 统一分配，定义里只声明可写字段，避免每新增来源都要手写优先级。\n  const roots: (Omit<SkillRoot, \"rank\"> & { rank?: number })[] = [\n    {\n      key: \"dsh\",\n      path: join(resolveDshHome(), \"skills\"),\n      label: \"DSH\",\n      mutable: true,\n      toggleable: true,\n      native: true,\n      rank: 400,\n    },\n    {\n      key: \"agents\",\n      path: join(resolveAgentsHome(), \"skills\"),\n      label: \"公共 Agent\",\n      mutable: true,\n      toggleable: true,\n      native: true,\n      rank: 450,\n    },\n    {\n      key: \"ccswitch\",\n      path: join(homedir(), \".cc-switch\", \"skills\"),\n      label: \"CC Switch\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"codex\",\n      path: join(\n        process.env.DSH_CODEX_HOME || join(homedir(), \".codex\"),\n        \"skills\",\n      ),\n      label: \"Codex\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"claude\",\n      path: join(\n        process.env.DSH_CLAUDE_HOME || join(homedir(), \".claude\"),\n        \"skills\",\n      ),\n      label: \"Claude Code\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"gemini\",\n      path: join(\n        process.env.DSH_GEMINI_HOME || join(homedir(), \".gemini\"),\n        \"skills\",\n      ),\n      label: \"Gemini\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"opencode\",\n      path: join(\n        process.env.DSH_OPENCODE_HOME || join(homedir(), \".config\", \"opencode\"),\n        \"skills\",\n      ),\n      label: \"OpenCode\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"cursor\",\n      path: join(\n        process.env.DSH_CURSOR_HOME || join(homedir(), \".cursor\"),\n        \"skills\",\n      ),\n      label: \"Cursor\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"copilot\",\n      path: join(process.env.DSH_COPILOT_HOME || join(homedir(), \".copilot\"), \"skills\"),\n      label: \"Copilot\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"windsurf\",\n      path: join(\n        process.env.DSH_WINDSURF_HOME || join(homedir(), \".codeium\", \"windsurf\"),\n        \"skills\",\n      ),\n      label: \"Windsurf\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"windsurf-user\",\n      localeKey: \"windsurfUser\",\n      path: join(\n        process.env.DSH_WINDSURF_USER_HOME || join(homedir(), \".windsurf\"),\n        \"skills\",\n      ),\n      label: \"Windsurf 主目录\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"trae\",\n      path: join(process.env.DSH_TRAE_HOME || join(homedir(), \".trae\"), \"skills\"),\n      label: \"Trae\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"trae-cn\",\n      localeKey: \"traeCn\",\n      path: join(\n        process.env.DSH_TRAE_CN_HOME || join(homedir(), \".trae-cn\"),\n        \"skills\",\n      ),\n      label: \"Trae 国内版\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"openclaw\",\n      path: join(\n        process.env.DSH_OPENCLAW_HOME || join(homedir(), \".openclaw\"),\n        \"skills\",\n      ),\n      label: \"OpenClaw\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"clawdbot\",\n      path: join(\n        process.env.DSH_CLAWDBOT_HOME || join(homedir(), \".clawdbot\"),\n        \"skills\",\n      ),\n      label: \"OpenClaw 旧目录\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"roo\",\n      path: join(process.env.DSH_ROO_HOME || join(homedir(), \".roo\"), \"skills\"),\n      label: \"Roo\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"codebuddy\",\n      path: join(\n        process.env.DSH_CODEBUDDY_HOME || join(homedir(), \".codebuddy\"),\n        \"skills\",\n      ),\n      label: \"CodeBuddy\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"workbuddy\",\n      localeKey: \"workbuddy\",\n      path: join(\n        process.env.DSH_WORKBUDDY_HOME || join(homedir(), \".workbuddy\"),\n        \"skills\",\n      ),\n      label: \"WorkBuddy\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"qoder\",\n      localeKey: \"qoder\",\n      path: join(process.env.DSH_QODER_HOME || join(homedir(), \".qoder\"), \"skills\"),\n      label: \"Qoder\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"qoder-cn\",\n      localeKey: \"qoderCn\",\n      path: join(\n        process.env.DSH_QODER_CN_HOME || join(homedir(), \".qoder-cn\"),\n        \"skills\",\n      ),\n      label: \"Qoder CN CLI\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"lingma\",\n      localeKey: \"lingma\",\n      path: join(process.env.DSH_LINGMA_HOME || join(homedir(), \".lingma\"), \"skills\"),\n      label: \"Qoder CN\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n    {\n      key: \"antigravity\",\n      localeKey: \"antigravity\",\n      path: join(\n        process.env.DSH_ANTIGRAVITY_HOME || join(homedir(), \".gemini\", \"config\"),\n        \"skills\",\n      ),\n      label: \"Google Antigravity\",\n      mutable: false,\n      toggleable: true,\n      native: false,\n    },\n  ];\n  const overrides = loadRootPathConfig().paths;\n  for (const root of roots) {\n    const override = overrides[root.key];\n    if (!override) continue;\n    root.defaultPath = root.path;\n    root.path = override;\n  }\n  // 用户登记的自定义来源：只读扫描，和预设外部来源同构，但目录与显示名由用户自己给。\n  for (const custom of loadRootPathConfig().customSources) {\n    roots.push({\n      key: custom.id,\n      path: custom.path,\n      label: custom.label,\n      ...(custom.group ? { group: custom.group } : {}),\n      mutable: false,\n      toggleable: true,\n      native: false,\n      custom: true,\n    });\n  }\n  return rankSources(roots, 500);\n}\n\nfunction projectIdentity(path: string) {\n  const canonical = pathIdentity(path);\n  return createHash(\"sha256\").update(canonical).digest(\"hex\").slice(0, 16);\n}\n\nasync function nearestProjectRoot(cwd: string) {\n  if (typeof cwd !== \"string\" || !isAbsolute(cwd)) return null;\n  let start;\n  try {\n    start = await fs.realpath(resolve(cwd));\n    if (!(await fs.stat(start)).isDirectory()) return null;\n  } catch {\n    return { unavailable: true, cwd };\n  }\n  let current = start;\n  for (;;) {\n    try {\n      await fs.lstat(join(current, \".git\"));\n      return { root: current, cwd: start };\n    } catch {\n      /* 继续向上查找最近的项目根 */\n    }\n    const parent = dirname(current);\n    // 与宿主一致：无 Git 标记时使用已校验的会话 cwd。\n    if (parent === current) return { root: start, cwd: start };\n    current = parent;\n  }\n}\n\nasync function projectSourceSafe(definition: SkillRoot) {\n  // 只读来源允许目录链接，但重叠来源会绕过用户根的停用策略。\n  const source = projectSourceDefinition(definition.kind);\n  if (!source) return false;\n  if (!source.mutable)\n    return !(await overlapsUserSkillRoot(definition.path));\n  const container = join(\n    definition.projectRoot!,\n    source.directory,\n  );\n  for (const path of [container, definition.path]) {\n    const st = await lstatOrNull(path);\n    if (st && (!st.isDirectory() || st.isSymbolicLink())) return false;\n  }\n  return !(await overlapsUserSkillRoot(definition.path));\n}\n\n/**\n * 从活动 Session cwd 推导项目技能根。只接受宿主上可解析的绝对目录，\n * 同一项目的多个 Session 会折叠到同一组稳定 key，避免跨 workspace 合并同名技能。\n */\nexport async function projectRoots(projectCwds: string[] = [], diagnostics?: Diagnostic[]): Promise<SkillRoot[]> {\n  const projects = new Map<string, {root: string; cwds: Set<string>}>();\n  for (const cwd of Array.isArray(projectCwds) ? projectCwds : []) {\n    const found = await nearestProjectRoot(cwd);\n    if (!found || !found.root) {\n      if (\n        found &&\n        found.unavailable &&\n        Array.isArray(diagnostics) &&\n        typeof cwd === \"string\" &&\n        isAbsolute(cwd)\n      ) {\n        diagnostics.push({\n          code: \"warning.project.unavailable\",\n          params: { path: cwd },\n          error: `无法从宿主读取活动工作区，项目技能未显示: ${cwd}`,\n        });\n      }\n      continue;\n    }\n    const identity = pathIdentity(found.root);\n    const existing = projects.get(identity) || {\n      root: found.root,\n      cwds: new Set<string>(),\n    };\n    existing.cwds.add(found.cwd);\n    projects.set(identity, existing);\n  }\n  const roots = [];\n  for (const project of [...projects.values()].sort((a, b) =>\n    a.root.localeCompare(b.root),\n  )) {\n    const id = projectIdentity(project.root);\n    const common = {\n      mutable: false,\n      toggleable: false,\n      native: true,\n      scope: \"project\",\n      projectRoot: project.root,\n      projectName: basename(project.root) || project.root,\n      workspaceCwds: [...project.cwds].sort(),\n    };\n    const candidates = PROJECT_SOURCES.map((source) => ({\n      ...common,\n      key: `project-${source.key}:${id}`,\n      kind: `project-${source.key}`,\n      localeKey: source.localeKey,\n      path: join(project.root, source.directory, \"skills\"),\n      label: source.label,\n      rank: source.rank,\n      mutable: source.mutable === true,\n      native: source.native === true,\n      toggleable: true,\n    }));\n    for (const candidate of candidates) {\n      if (candidate.kind !== \"project-dsh\" && !(await lstatOrNull(candidate.path)))\n        continue;\n      if (await projectSourceSafe(candidate)) roots.push(candidate);\n    }\n  }\n  return roots;\n}\n\n/** 工作区路径比较：与项目根同一套规范化，Windows 下不区分大小写。 */\nfunction sameWorkspace(a: string, b: string) {\n  return pathIdentity(a) === pathIdentity(b);\n}\n\nexport function createWorkspaceIndex(registered?: string[], hooks?: { onBuild?: () => void }) {\n  let pending: Promise<Array<{ root: SkillRoot } | OperationError>> | undefined;\n  return {\n    registered,\n    load() {\n      if (!pending) {\n        hooks?.onBuild?.();\n        pending = indexRegisteredWorkspaces(registered);\n      }\n      return pending;\n    },\n  };\n}\n\nexport async function indexRegisteredWorkspaces(registered?: string[]): Promise<Array<{ root: SkillRoot } | OperationError>> {\n  const list = Array.isArray(registered) ? registered.filter((item): item is string => typeof item === \"string\") : [];\n  const indexed: Array<{ root: SkillRoot } | OperationError> = [];\n  for (const workspace of list) indexed.push(await resolveWorkspaceTarget(workspace, list));\n  return indexed;\n}\n\n/**\n * 按安装记录里保存的项目根重新解析可写根。记录只保存路径，不代表授权：\n * 每次更新、回滚、卸载都要重新核对链接与重叠，路径失效时明确失败而不是回退到别处。\n * 批量调用可传入同一次请求里已经解析好的登记索引，避免每个记录都重走全部工作区。\n */\nexport async function projectRootForRecord(projectRoot: unknown, registered?: string[], indexed?: Array<{ root: SkillRoot } | OperationError>): Promise<{ root: SkillRoot } | OperationError> {\n  if (typeof projectRoot !== \"string\" || !isAbsolute(projectRoot))\n    return { ok: false, error: \"安装记录中的工作区路径无效\", code: \"error.workspace.unavailable\" };\n  const saved = await nearestProjectRoot(projectRoot);\n  if (!saved?.root || !sameWorkspace(saved.root, projectRoot))\n    return { ok: false, error: `工作区目录不可用: ${projectRoot}`, code: \"error.workspace.unavailable\", params: { path: projectRoot } };\n  for (const target of indexed ?? await indexRegisteredWorkspaces(registered)) {\n    if (\"root\" in target && sameWorkspace(target.root.projectRoot!, projectRoot)) return target;\n  }\n  return { ok: false, error: \"请选择已登记的工作区\", code: \"error.workspace.unregistered\" };\n}\n\n/**\n * 把「已登记工作区」解析成可写的项目 DSH 根。\n * - 路径必须出现在宿主登记列表里；列表缺失或为空一律拒绝，不信任前端传来的路径。\n * - 项目根沿用 projectRoots 的规则：最近 Git 根，没有则用该目录。\n * - 只开放 .dsh/skills，沿用链接与用户目录重叠检查；解析本身不创建目录。\n */\nexport async function resolveWorkspaceTarget(\n  workspace: unknown,\n  registered: unknown,\n): Promise<{ root: SkillRoot } | OperationError> {\n  const unregistered: OperationError = {\n    ok: false,\n    error: \"请选择已登记的工作区\",\n    code: \"error.workspace.unregistered\",\n  };\n  if (typeof workspace !== \"string\" || !workspace.trim() || !isAbsolute(workspace.trim())) return unregistered;\n  const requested = workspace.trim();\n  const list = Array.isArray(registered)\n    ? registered.filter((item): item is string => typeof item === \"string\" && isAbsolute(item))\n    : [];\n  if (!list.some((item) => sameWorkspace(item, requested))) return unregistered;\n  const found = await nearestProjectRoot(requested);\n  if (!found || !found.root)\n    return {\n      ok: false,\n      error: `工作区目录不可用: ${requested}`,\n      code: \"error.workspace.unavailable\",\n      params: { path: requested },\n    };\n  const source = PROJECT_SOURCES.find((item) => item.key === \"dsh\")!;\n  const root: SkillRoot = {\n    key: `project-dsh:${projectIdentity(found.root)}`,\n    kind: \"project-dsh\",\n    scope: \"project\",\n    localeKey: source.localeKey,\n    label: source.label,\n    rank: source.rank,\n    mutable: true,\n    native: true,\n    toggleable: true,\n    path: join(found.root, source.directory, \"skills\"),\n    projectRoot: found.root,\n    projectName: basename(found.root) || found.root,\n    workspaceCwds: [found.cwd],\n  };\n  const checked = await checkedWritableRootDefinition(root);\n  if (!checked) return unregistered;\n  if (checked.ok === false) return checked;\n  return { root: checked as SkillRoot };\n}\n\nexport function managerHomePath() {\n  return join(resolveDshHome(), \"skills-manager\");\n}\n\nexport function managerStatePath() {\n  return join(managerHomePath(), \"state.json\");\n}\n\nexport function trashRootPath() {\n  return join(managerHomePath(), \"trash\");\n}\n\nexport function logPath() {\n  return join(resolveDshHome(), \"dsh-skills-manager.log\");\n}\n\n// ── 外部来源目录覆盖 ────────────────────────────────────────────────────────\n\nconst ROOTS_CONFIG_VERSION = 1;\nconst MAX_ROOT_PATH_LENGTH = 1024;\n/**\n * 只有外部只读来源允许改写目录。DSH / 公共 Agent 是宿主的扫描路径，\n * 单独改这里会出现「写进去却读不到」，要搬迁请用 DSH_HOME / DSH_AGENTS_HOME。\n */\nconst OVERRIDABLE_ROOT_KEYS = new Set(EXTERNAL_SOURCE_ORDER);\n\ninterface CustomSourceConfig {\n  id: string;\n  label: string;\n  path: string;\n  group?: string;\n}\ninterface RootPathConfig {\n  paths: Record<string, string>;\n  customSources: CustomSourceConfig[];\n  warnings: Diagnostic[];\n}\n\n/** roots.json 读取一次后常驻内存；写入时同步替换，手工改文件需重启 DSH。 */\nlet rootPathConfig: RootPathConfig | null = null;\n\n/** 覆盖配置的位置，与 state.json、trash 同级。 */\nexport function rootPathConfigPath() {\n  return join(managerHomePath(), \"roots.json\");\n}\n\nfunction rootPathError(\n  code: string,\n  message: string,\n  params: Record<string, unknown> = {},\n): OperationError {\n  return { ok: false, code, params, error: message };\n}\n\nfunction corruptRootPathConfig(file: string, reason: string): RootPathConfig {\n  return {\n    paths: {},\n    customSources: [],\n    warnings: [\n      {\n        code: \"warning.rootPath.corrupt\",\n        params: { path: file },\n        error: `${reason}，已使用默认目录: ${file}`,\n      },\n    ],\n  };\n}\n\n/** 显示名 → 稳定的 ASCII slug；中文等非 ASCII 名称退化为 source，靠后缀去重。 */\nfunction customSourceSlug(label: string) {\n  const slug = label\n    .toLowerCase()\n    .replace(/[^a-z0-9]+/g, \"-\")\n    .replace(/^-+|-+$/g, \"\")\n    .slice(0, 24);\n  return slug || \"source\";\n}\n\nfunction normalizeCustomLabel(value: unknown) {\n  const label = typeof value === \"string\" ? value.trim() : \"\";\n  return label && label.length <= MAX_CUSTOM_LABEL_LENGTH ? label : \"\";\n}\n\n/** 逐条解析 customSources：非法条目只跳过自己，不影响路径覆盖与其它自定义来源。 */\nfunction parseCustomSources(value: unknown, warnings: Diagnostic[]): CustomSourceConfig[] {\n  if (value === undefined) return [];\n  if (!Array.isArray(value)) {\n    warnings.push({\n      code: \"warning.rootPath.invalid\",\n      params: { path: \"customSources\" },\n      error: \"自定义来源配置必须是数组，已忽略: customSources\",\n    });\n    return [];\n  }\n  const accepted: CustomSourceConfig[] = [];\n  const ids = new Set<string>();\n  const paths = new Set<string>();\n  for (const entry of value.slice(0, MAX_CUSTOM_SOURCES)) {\n    const record = entry && typeof entry === \"object\" && !Array.isArray(entry) ? (entry as Record<string, unknown>) : null;\n    const id = record && typeof record.id === \"string\" ? record.id.trim() : \"\";\n    const label = record ? normalizeCustomLabel(record.label) : \"\";\n    const requested = record && typeof record.path === \"string\" ? record.path.trim() : \"\";\n    const group = record && typeof record.group === \"string\" ? normalizeCustomLabel(record.group) : \"\";\n    const identity = requested && isAbsolute(requested) ? pathIdentity(requested) : \"\";\n    if (\n      !record || !CUSTOM_SOURCE_ID_RE.test(id) || !label || !requested ||\n      !isAbsolute(requested) || requested.length > MAX_ROOT_PATH_LENGTH ||\n      ids.has(id) || paths.has(identity)\n    ) {\n      const key = id || (record && typeof record.id === \"string\" ? record.id : \"customSources\");\n      warnings.push({\n        code: \"warning.rootPath.invalid\",\n        params: { path: key },\n        error: `自定义来源配置项无效，已忽略: ${key}`,\n      });\n      continue;\n    }\n    ids.add(id);\n    paths.add(identity);\n    accepted.push({ id, label, path: resolve(requested), ...(group ? { group } : {}) });\n  }\n  return accepted;\n}\n\n/** 逐条忽略损坏或非法的配置项，不影响其它来源，也不触发 state.json 的 fail-closed。 */\nfunction readRootPathConfigFile(): RootPathConfig {\n  const file = rootPathConfigPath();\n  let raw: string;\n  try {\n    raw = readFileSync(file, \"utf8\");\n  } catch (caught) {\n    const error = caught as CodedError;\n    if (error && error.code === \"ENOENT\") return { paths: {}, customSources: [], warnings: [] };\n    return corruptRootPathConfig(file, \"技能目录配置不可读\");\n  }\n  let document: unknown;\n  try {\n    document = JSON.parse(raw);\n  } catch {\n    return corruptRootPathConfig(file, \"技能目录配置不是合法 JSON\");\n  }\n  const paths =\n    document && typeof document === \"object\" && !Array.isArray(document)\n      ? (document as { paths?: unknown }).paths\n      : undefined;\n  if (!paths || typeof paths !== \"object\" || Array.isArray(paths))\n    return corruptRootPathConfig(file, \"技能目录配置缺少 paths 对象\");\n  const accepted: Record<string, string> = {};\n  const warnings: Diagnostic[] = [];\n  for (const [key, value] of Object.entries(paths as Record<string, unknown>)) {\n    const requested = typeof value === \"string\" ? value.trim() : \"\";\n    // 未登记来源和非绝对路径都只跳过这一条，其它来源的覆盖照常生效。\n    if (!OVERRIDABLE_ROOT_KEYS.has(key) || !requested || !isAbsolute(requested)) {\n      warnings.push({\n        code: \"warning.rootPath.invalid\",\n        params: { path: key },\n        error: `技能目录配置项无效，已忽略: ${key}`,\n      });\n      continue;\n    }\n    accepted[key] = resolve(requested);\n  }\n  const customSources = parseCustomSources(\n    document && typeof document === \"object\" && !Array.isArray(document)\n      ? (document as { customSources?: unknown }).customSources\n      : undefined,\n    warnings,\n  );\n  return { paths: accepted, customSources, warnings };\n}\n\nfunction loadRootPathConfig(): RootPathConfig {\n  if (!rootPathConfig) rootPathConfig = readRootPathConfigFile();\n  return rootPathConfig;\n}\n\n/** 重新读取 roots.json；供测试与「手工改文件后重启」的等价入口使用。 */\nexport function reloadRootPathOverrides() {\n  rootPathConfig = null;\n  return loadRootPathConfig();\n}\n\n/**\n * 原子写入 roots.json。路径覆盖与自定义来源共用同一个文件，写一次同步两个段落，\n * 避免两次写入之间留下半套配置；写入失败时不改动内存里的旧配置。\n */\nasync function writeRootPathConfig(\n  config: RootPathConfig,\n  next: { paths?: Record<string, string>; customSources?: CustomSourceConfig[] },\n) {\n  const paths = Object.fromEntries(\n    Object.entries(next.paths ?? config.paths).sort(([left], [right]) =>\n      left.localeCompare(right),\n    ),\n  );\n  const customSources = next.customSources ?? config.customSources;\n  await fs.mkdir(managerHomePath(), { recursive: true });\n  await writeFileAtomically(\n    rootPathConfigPath(),\n    `${JSON.stringify({ version: ROOTS_CONFIG_VERSION, paths, customSources }, null, 2)}\\n`,\n  );\n  config.paths = paths;\n  config.customSources = customSources;\n  config.warnings = [];\n}\n\nasync function writeRootPathOverrides(\n  config: RootPathConfig,\n  key: string,\n  value: string | null,\n) {\n  const paths = { ...config.paths };\n  if (value === null) delete paths[key];\n  else paths[key] = value;\n  await writeRootPathConfig(config, { paths });\n}\n\n/** 只读来源目录的共用校验：绝对路径、长度、存在、是目录、不与状态目录或其它来源重叠。 */\nasync function validateSourceRootPath(\n  requested: string,\n  options: { excludeKey?: string } = {},\n): Promise<{ ok: true; path: string } | OperationError> {\n  if (!isAbsolute(requested))\n    return rootPathError(\n      \"error.rootPath.absolute\",\n      `技能目录必须是绝对路径: ${requested}`,\n      { path: requested },\n    );\n  if (requested.length > MAX_ROOT_PATH_LENGTH)\n    return rootPathError(\n      \"error.rootPath.tooLong\",\n      `技能目录路径超过 ${MAX_ROOT_PATH_LENGTH} 个字符: ${requested}`,\n      { path: requested },\n    );\n  let info;\n  try {\n    info = await fs.stat(requested);\n  } catch {\n    return rootPathError(\n      \"error.rootPath.notFound\",\n      `技能目录不存在: ${requested}`,\n      { path: requested },\n    );\n  }\n  if (!info.isDirectory())\n    return rootPathError(\n      \"error.rootPath.notDirectory\",\n      `技能目录不是文件夹: ${requested}`,\n      { path: requested },\n    );\n  const candidate = await comparisonPath(requested);\n  const managerHome = await comparisonPath(managerHomePath());\n  if (\n    isSameOrDescendant(managerHome, candidate) ||\n    isSameOrDescendant(candidate, managerHome)\n  )\n    return rootPathError(\n      \"error.rootPath.reserved\",\n      `技能目录不能与技能管理器的状态目录重叠: ${requested}`,\n      { path: requested },\n    );\n  // 覆盖后的路径也要参与重叠判断，否则两个来源可以指向同一棵树而绕过去重与停用策略。\n  for (const other of userRoots()) {\n    if (other.key === options.excludeKey) continue;\n    const otherPath = await comparisonPath(other.path);\n    if (\n      isSameOrDescendant(candidate, otherPath) ||\n      isSameOrDescendant(otherPath, candidate)\n    )\n      return rootPathError(\n        \"error.rootPath.overlap\",\n        `技能目录不能与其它技能来源重叠: ${other.path}`,\n        { path: requested },\n      );\n  }\n  return { ok: true, path: resolve(requested) };\n}\n\n/**\n * 改写或恢复某个外部来源的技能目录。\n * 只校验「读哪里」，不移动、不创建任何目录；保存后由调用方触发目录缓存失效。\n */\nexport async function setRootPath(\n  key: unknown,\n  value: unknown,\n): Promise<\n  | { ok: true; root: { key: string; path: string; defaultPath?: string } }\n  | OperationError\n> {\n  const rootKey = typeof key === \"string\" ? key.trim() : \"\";\n  const current = userRoots().find((root) => root.key === rootKey);\n  // 自定义来源的目录存在 customSources 段：恢复默认等价于移除登记，避免留下空目录来源。\n  if (rootKey && isCustomSourceKey(rootKey)) {\n    if (!current)\n      return rootPathError(\n        \"error.rootPath.unsupported\",\n        `该技能来源不支持修改目录: ${rootKey}`,\n        { root: rootKey },\n      );\n    if (\n      value === null ||\n      value === undefined ||\n      (typeof value === \"string\" && value.trim() === \"\")\n    ) {\n      const removed = await removeCustomSource(rootKey);\n      if (removed.ok === false) return removed;\n      return { ok: true, root: { key: rootKey, path: current.path } };\n    }\n    const updated = await updateCustomSource(rootKey, { path: value });\n    if (updated.ok === false) return updated;\n    return { ok: true, root: { key: rootKey, path: updated.source.path } };\n  }\n  // OVERRIDABLE_ROOT_KEYS 只含外部只读来源，DSH / 公共 Agent / 项目来源都天然被排除。\n  if (!rootKey || !current || !OVERRIDABLE_ROOT_KEYS.has(rootKey))\n    return rootPathError(\n      \"error.rootPath.unsupported\",\n      `该技能来源不支持修改目录: ${rootKey || \"(空)\"}`,\n      { root: rootKey || \"(empty)\" },\n    );\n  const config = loadRootPathConfig();\n  const defaultPath = current.defaultPath || current.path;\n  // null / 空字符串 / 与默认值相同都表示恢复默认，避免把默认值写成一条显式覆盖。\n  if (\n    value === null ||\n    value === undefined ||\n    (typeof value === \"string\" && value.trim() === \"\")\n  ) {\n    await writeRootPathOverrides(config, rootKey, null);\n    return { ok: true, root: { key: rootKey, path: defaultPath } };\n  }\n  if (typeof value !== \"string\")\n    return rootPathError(\n      \"error.rootPath.invalid\",\n      `技能目录必须是文本路径: ${String(value)}`,\n      { path: String(value) },\n    );\n  const requested = value.trim();\n  if (pathIdentity(requested) === pathIdentity(defaultPath)) {\n    await writeRootPathOverrides(config, rootKey, null);\n    return { ok: true, root: { key: rootKey, path: defaultPath } };\n  }\n  const checked = await validateSourceRootPath(requested, { excludeKey: rootKey });\n  if (checked.ok === false) return checked;\n  await writeRootPathOverrides(config, rootKey, checked.path);\n  return { ok: true, root: { key: rootKey, path: checked.path, defaultPath } };\n}\n\n// ── 自定义来源登记 ──────────────────────────────────────────────────────────\n\nfunction nextCustomSourceId(label: string, taken: Set<string>) {\n  const base = CUSTOM_SOURCE_PREFIX + customSourceSlug(label);\n  if (!taken.has(base)) return base;\n  for (let index = 2; index <= MAX_CUSTOM_SOURCES + 1; index++) {\n    const candidate = `${base}-${index}`;\n    if (!taken.has(candidate)) return candidate;\n  }\n  return \"\";\n}\n\n/**\n * 登记一个或多个自定义来源（单目录或扫描结果）。\n * 目录必须已存在且不与现有来源重叠；重复目录是幂等的，不会加出第二份。\n */\nexport async function addCustomSources(input: unknown) {\n  const config = loadRootPathConfig();\n  const list = Array.isArray(input) ? input : [input];\n  if (!list.length)\n    return rootPathError(\"error.customSource.empty\", \"没有要添加的技能来源\", {});\n  const taken = new Set(userRoots().map((root) => root.key));\n  const next = [...config.customSources];\n  const added: CustomSourceConfig[] = [];\n  for (const entry of list) {\n    if (next.length >= MAX_CUSTOM_SOURCES)\n      return rootPathError(\n        \"error.customSource.limit\",\n        `自定义来源数量已达上限 ${MAX_CUSTOM_SOURCES} 个`,\n        { limit: MAX_CUSTOM_SOURCES },\n      );\n    const record = entry && typeof entry === \"object\" ? (entry as Record<string, unknown>) : null;\n    const requested = record && typeof record.path === \"string\" ? record.path.trim() : \"\";\n    // 同一个目录重复登记是幂等的：先按 identity 跳过，否则会被自己的来源判成重叠。\n    if (\n      requested &&\n      isAbsolute(requested) &&\n      next.some((item) => pathIdentity(item.path) === pathIdentity(requested))\n    )\n      continue;\n    const checked = await validateSourceRootPath(requested);\n    if (checked.ok === false) return checked;\n    const label = (record && normalizeCustomLabel(record.label)) || basename(checked.path);\n    if (!label)\n      return rootPathError(\n        \"error.customSource.label\",\n        `自定义来源必须有显示名: ${checked.path}`,\n        { path: checked.path },\n      );\n    if (next.some((item) => pathIdentity(item.path) === pathIdentity(checked.path)))\n      continue;\n    const id = nextCustomSourceId(label, taken);\n    if (!id)\n      return rootPathError(\n        \"error.customSource.limit\",\n        `自定义来源数量已达上限 ${MAX_CUSTOM_SOURCES} 个`,\n        { limit: MAX_CUSTOM_SOURCES },\n      );\n    taken.add(id);\n    const group = record ? normalizeCustomLabel(record.group) : \"\";\n    const source: CustomSourceConfig = {\n      id,\n      label,\n      path: checked.path,\n      ...(group ? { group } : {}),\n    };\n    next.push(source);\n    added.push(source);\n  }\n  if (added.length) await writeRootPathConfig(config, { customSources: next });\n  return { ok: true as const, added };\n}\n\n/** 改写自定义来源的显示名或目录；只动登记信息，不碰任何文件。 */\nexport async function updateCustomSource(key: unknown, patch: unknown) {\n  const id = typeof key === \"string\" ? key.trim() : \"\";\n  const config = loadRootPathConfig();\n  const index = config.customSources.findIndex((item) => item.id === id);\n  if (!CUSTOM_SOURCE_ID_RE.test(id) || index < 0)\n    return rootPathError(\n      \"error.customSource.unknown\",\n      `未登记的自定义来源: ${id || \"(空)\"}`,\n      { root: id },\n    );\n  const record = patch && typeof patch === \"object\" ? (patch as Record<string, unknown>) : {};\n  const current = config.customSources[index];\n  const label = record.label === undefined ? current.label : normalizeCustomLabel(record.label);\n  if (!label)\n    return rootPathError(\n      \"error.customSource.label\",\n      `自定义来源必须有显示名: ${String(record.label)}`,\n      { path: String(record.label) },\n    );\n  let path = current.path;\n  if (record.path !== undefined) {\n    const requested = typeof record.path === \"string\" ? record.path.trim() : \"\";\n    const checked = await validateSourceRootPath(requested, { excludeKey: id });\n    if (checked.ok === false) return checked;\n    path = checked.path;\n  }\n  const group =\n    record.group === undefined ? current.group : normalizeCustomLabel(record.group) || undefined;\n  const source: CustomSourceConfig = { id, label, path, ...(group ? { group } : {}) };\n  const next = config.customSources.map((item, position) =>\n    position === index ? source : item,\n  );\n  await writeRootPathConfig(config, { customSources: next });\n  return { ok: true as const, source };\n}\n\n/** 移除登记；技能文件保持原样，面板只是不再扫描这个目录。 */\nexport async function removeCustomSource(key: unknown) {\n  const id = typeof key === \"string\" ? key.trim() : \"\";\n  const config = loadRootPathConfig();\n  if (!config.customSources.some((item) => item.id === id))\n    return rootPathError(\n      \"error.customSource.unknown\",\n      `未登记的自定义来源: ${id || \"(空)\"}`,\n      { root: id },\n    );\n  await writeRootPathConfig(config, {\n    customSources: config.customSources.filter((item) => item.id !== id),\n  });\n  return { ok: true as const, removed: id };\n}\n\n/**\n * 在一个总目录下找「技能汇总目录」，只向下探索 MAX_SOURCE_SCAN_DEPTH 层。\n * 返回的候选只描述现状，登记动作仍由用户确认后调用 addCustomSources。\n */\nasync function collectSkillDirectories(root: string) {\n  const found: { path: string; depth: number; segments: string[] }[] = [];\n  async function walk(directory: string, depth: number, segments: string[]) {\n    if (found.length >= MAX_SOURCE_SCAN_CANDIDATES) return;\n    const skillsDir = join(directory, \"skills\");\n    if ((await lstatOrNull(skillsDir))?.isDirectory())\n      found.push({ path: skillsDir, depth, segments });\n    if (depth >= MAX_SOURCE_SCAN_DEPTH) return;\n    let entries;\n    try {\n      entries = await fs.readdir(directory, { withFileTypes: true });\n    } catch {\n      return;\n    }\n    for (const entry of entries) {\n      if (found.length >= MAX_SOURCE_SCAN_CANDIDATES) return;\n      if (!entry.isDirectory()) continue;\n      // 跳过隐藏目录、依赖目录与 skills 自身，避免把普通资源目录当成来源。\n      if (entry.name.startsWith(\".\") || entry.name === \"skills\" || entry.name === \"node_modules\")\n        continue;\n      await walk(join(directory, entry.name), depth + 1, segments.concat(entry.name));\n    }\n  }\n  await walk(root, 0, []);\n  return found;\n}\n\n/** 扫描候选来源：显示名默认取目录名，总目录名作为分组，界面上就能看到产品名而不是「非标」。 */\nexport async function scanCustomSourceCandidates(inputPath: unknown) {\n  const requested = typeof inputPath === \"string\" ? inputPath.trim() : \"\";\n  if (!requested || !isAbsolute(requested))\n    return rootPathError(\n      \"error.rootPath.absolute\",\n      `技能目录必须是绝对路径: ${requested || \"(空)\"}`,\n      { path: requested },\n    );\n  if (requested.length > MAX_ROOT_PATH_LENGTH)\n    return rootPathError(\n      \"error.rootPath.tooLong\",\n      `技能目录路径超过 ${MAX_ROOT_PATH_LENGTH} 个字符: ${requested}`,\n      { path: requested },\n    );\n  let info;\n  try {\n    info = await fs.stat(requested);\n  } catch {\n    return rootPathError(\n      \"error.rootPath.notFound\",\n      `技能目录不存在: ${requested}`,\n      { path: requested },\n    );\n  }\n  if (!info.isDirectory())\n    return rootPathError(\n      \"error.rootPath.notDirectory\",\n      `技能目录不是文件夹: ${requested}`,\n      { path: requested },\n    );\n  const root = resolve(requested);\n  const product = basename(root) || root;\n  const registered = new Set(userRoots().map((item) => pathIdentity(item.path)));\n  const candidates = [];\n  for (const item of await collectSkillDirectories(root)) {\n    const skills = await discoverReadonlyEntries(item.path);\n    candidates.push({\n      path: item.path,\n      label: item.depth === 0 ? product : [product].concat(item.segments).join(\" / \"),\n      group: product,\n      depth: item.depth,\n      skillCount: skills.entries.length,\n      // 与已有来源重叠的候选仍然列出来，但界面要禁止登记，否则会绕过停用策略。\n      conflict: await overlapsUserSkillRoot(item.path),\n      registered: registered.has(pathIdentity(item.path)),\n    });\n  }\n  return { ok: true as const, root, candidates };\n}\n\n/**\n * 为前端内嵌目录选择器列出一个本机目录层级。\n * 不跟随目录符号链接；选择后的导入仍由 importSkill 做完整安全校验。\n */\nexport async function browseDirectories(inputPath: string) {\n  const requested = String(inputPath == null ? \"\" : inputPath).trim();\n  const target = requested === \"\" ? homedir() : requested;\n  if (!isAbsolute(target)) {\n    return {\n      ok: false,\n      error: `目录路径必须是绝对路径: ${target}`,\n      code: \"error.browse.absolute\",\n      params: { path: target },\n    };\n  }\n\n  let canonical;\n  let directory;\n  try {\n    canonical = await fs.realpath(target);\n    directory = await fs.stat(canonical);\n  } catch (caught) { const error = caught as CodedError;\n    return {\n      ok: false,\n      error: `无法读取目录: ${target}`,\n      code: \"error.browse.unreadable\",\n      params: {\n        path: target,\n        error: String(error && error.message ? error.message : error),\n      },\n    };\n  }\n  if (!directory.isDirectory()) {\n    return {\n      ok: false,\n      error: `不是目录: ${target}`,\n      code: \"error.browse.notDirectory\",\n      params: { path: target },\n    };\n  }\n\n  const entries = [];\n  let truncated = false;\n  try {\n    const items = await fs.readdir(canonical, { withFileTypes: true });\n    for (const item of items) {\n      // 目录链接不在浏览器中展开，避免选择器在不知情时跨越到另一棵目录树。\n      if (!item.isDirectory() || item.isSymbolicLink()) continue;\n      // Dirent 来自一次目录快照；再用 lstat 校验当前条目，既收紧 TOCTOU 窗口，\n      // 也明确排除 Windows junction 等重解析目录。\n      const childPath = join(canonical, item.name);\n      const childStat = await lstatOrNull(childPath);\n      if (!childStat || !childStat.isDirectory() || childStat.isSymbolicLink())\n        continue;\n      if (entries.length >= MAX_BROWSE_ENTRIES) {\n        truncated = true;\n        break;\n      }\n      entries.push({\n        name: item.name,\n        path: childPath,\n        hidden: item.name.startsWith(\".\"),\n      });\n    }\n  } catch (caught) { const error = caught as CodedError;\n    return {\n      ok: false,\n      error: `无法读取目录: ${canonical}`,\n      code: \"error.browse.unreadable\",\n      params: {\n        path: canonical,\n        error: String(error && error.message ? error.message : error),\n      },\n    };\n  }\n  entries.sort((a, b) =>\n    a.name.localeCompare(b.name, undefined, {\n      sensitivity: \"base\",\n      numeric: true,\n    }),\n  );\n\n  const crumbs = [];\n  let cursor = canonical;\n  for (;;) {\n    const parent = dirname(cursor);\n    crumbs.unshift({\n      name: parent === cursor ? cursor : basename(cursor),\n      path: cursor,\n      hidden: false,\n    });\n    if (parent === cursor) break;\n    cursor = parent;\n  }\n  return { path: canonical, home: homedir(), crumbs, entries, truncated };\n}\n\nfunction dshRootPath() {\n  return userRoots().find((root) => root.key === \"dsh\")!.path;\n}\n\n/** 只读来源的拒绝结果；action 为可翻译语义值（toggle/delete）。 */\nfunction readonlyError(action: string): OperationError {\n  return {\n    ok: false,\n    code: \"error.root.readonly\",\n    params: { action },\n    error:\n      action === \"delete\"\n        ? \"该技能来源不允许删除\"\n        : \"该技能来源不允许启用或停用\",\n  };\n}\n\nfunction rootDefinition(root: RootInput): SkillRoot | null {\n  if (root && typeof root === \"object\" && typeof root.key === \"string\")\n    return root;\n  if (typeof root !== \"string\") return null;\n  const resolved = resolve(root);\n  return userRoots().find((item) => resolve(item.path) === resolved) || null;\n}\n\nfunction rootByKey(key: string): SkillRoot | null | undefined {\n  return userRoots().find((item) => item.key === key) || null;\n}\n\n/** 只允许用户 DSH、Shared Agent，或由活动 Session 推导出的项目 DSH 根参与文件写入。 */\nfunction writableRootDefinition(root: RootInput) {\n  const definition = rootDefinition(root);\n  // Shared Agent 统一开放管理，但仍必须是当前配置的规范目录。\n  if (definition?.key === \"agents\") {\n    const canonical = rootByKey(\"agents\");\n    return canonical && resolve(definition.path) === resolve(canonical.path)\n      ? canonical\n      : null;\n  }\n  if (!definition || definition.mutable !== true) return null;\n  if (definition.key === \"dsh\")\n    return resolve(definition.path) === resolve(dshRootPath())\n      ? rootByKey(\"dsh\")\n      : null;\n  if (\n    definition.scope !== \"project\" ||\n    definition.kind !== \"project-dsh\" ||\n    typeof definition.projectRoot !== \"string\" ||\n    !isAbsolute(definition.projectRoot!) ||\n    definition.key !==\n      `project-dsh:${projectIdentity(definition.projectRoot!)}` ||\n    resolve(definition.path) !==\n      resolve(join(definition.projectRoot!, \".dsh\", \"skills\"))\n  )\n    return null;\n  return definition;\n}\n\n/** 用户级安装目标及 Shared Agent 普通写入均禁止祖先目录链接。 */\nasync function checkedUserRootAncestors(definition: SkillRoot): Promise<SkillRoot | OperationError> {\n  for (let path = resolve(definition.path); ; path = dirname(path)) {\n    const st = await lstatOrNull(path);\n    if (st && (!st.isDirectory() || st.isSymbolicLink()))\n      return { ok: false, error: `技能目录不安全，拒绝写入: ${path}`, code: \"error.root.unsafe\", params: { path } };\n    if (dirname(path) === path) break;\n  }\n  return definition;\n}\n\nasync function checkedWritableRootDefinition(root: RootInput): Promise<SkillRoot | OperationError | null | undefined> {\n  const definition = writableRootDefinition(root);\n  if (definition?.key === \"agents\") return checkedUserRootAncestors(definition);\n  if (!definition || definition.scope !== \"project\") return definition;\n  if (await overlapsUserSkillRoot(definition.path)) {\n    return {\n      ok: false,\n      error: `项目技能目录与用户技能目录重叠，拒绝写入: ${definition.path}`,\n      code: \"error.root.unsafe\",\n      params: { path: definition.path },\n    };\n  }\n  // 项目仓库内容不可信；拒绝通过 .dsh 或 skills 链接把写入重定向到项目之外。\n  for (const path of [join(definition.projectRoot!, \".dsh\"), definition.path]) {\n    const st = await lstatOrNull(path);\n    if (st && (!st.isDirectory() || st.isSymbolicLink())) {\n      return {\n        ok: false,\n        error: `项目技能目录不安全，拒绝写入: ${path}`,\n        code: \"error.root.unsafe\",\n        params: { path },\n      };\n    }\n  }\n  return definition;\n}\n\n/** 仓库安装目标统一检查祖先路径；不改变普通 DSH 管理对迁移 Home 的兼容。 */\nexport async function checkedRepositoryRootDefinition(root: RootInput): Promise<SkillRoot | OperationError | null | undefined> {\n  const definition = await checkedWritableRootDefinition(root);\n  if (!definition || definition.ok === false || definition.scope === \"project\" || definition.key === \"agents\") return definition;\n  return checkedUserRootAncestors(definition);\n}\n\n/** 仓库可选的安装位置：全局 DSH，以及已配置的公共 Agent 目录。 */\nexport async function repositoryDestinations(): Promise<RepositoryDestination[]> {\n  const result: RepositoryDestination[] = [];\n  for (const root of userRoots().filter(item => item.key === \"dsh\" || item.key === \"agents\")) {\n    let error: Diagnostic | undefined;\n    try {\n      const checked = await checkedRepositoryRootDefinition(root);\n      if (!checked || checked.ok === false) error = checked || { code: \"error.root.unsafe\", error: \"技能安装位置不可用\" };\n    } catch (caught) { const exception = caught as CodedError; error = { code: \"error.root.unsafe\", error: exception.message, params: { path: root.path } }; }\n    result.push({ key: root.key as RepositoryDestination['key'], path: resolve(root.path), label: root.label, localeKey: root.localeKey, available: !error, ...(error ? { error } : {}) });\n  }\n  return result;\n}\n\n/** 判断 child 是否与 parent 相同或位于其内部。跨盘符时 relative 会返回绝对路径。 */\nfunction isSameOrDescendant(parent: string, child: string) {\n  const rel = relative(resolve(parent), resolve(child));\n  return (\n    rel === \"\" ||\n    (!isAbsolute(rel) && rel !== \"..\" && !rel.startsWith(`..${sep}`))\n  );\n}\n\n/** 解析真实路径；中间若有目录链接，按落地目录比较重叠。 */\nasync function resolvedPath(path: string) {\n  try {\n    return await fs.realpath(path);\n  } catch {\n    return resolve(path);\n  }\n}\n\n/** 即使末级路径尚不存在，也解析最近既存祖先中的链接，供权限域重叠判断。 */\nasync function comparisonPath(path: string) {\n  let current = resolve(path);\n  const missing = [];\n  for (;;) {\n    try {\n      return resolve(await fs.realpath(current), ...missing);\n    } catch {\n      const parent = dirname(current);\n      if (parent === current) return resolve(path);\n      missing.unshift(basename(current));\n      current = parent;\n    }\n  }\n}\n\nasync function overlapsUserSkillRoot(path: string) {\n  const candidate = await comparisonPath(path);\n  for (const root of userRoots()) {\n    const userPath = await comparisonPath(root.path);\n    if (\n      isSameOrDescendant(candidate, userPath) ||\n      isSameOrDescendant(userPath, candidate)\n    )\n      return true;\n  }\n  return false;\n}\n\n/** 两个路径重叠时，覆盖导入可能删除自身来源，必须拒绝。 */\nasync function pathsOverlap(a: string, b: string) {\n  const left = await resolvedPath(a);\n  const right = await resolvedPath(b);\n  return isSameOrDescendant(left, right) || isSameOrDescendant(right, left);\n}\n\n/** 预解析技能根后的根内校验，供逐条目扫描复用同一次 realpath，减少重复 IO。 */\nasync function isInsideResolvedRoot(rootReal: string, path: string) {\n  return isSameOrDescendant(rootReal, await resolvedPath(path));\n}\n\nfunction pathIdentity(path: string) {\n  const canonical = resolve(path);\n  return process.platform === \"win32\" ? canonical.toLowerCase() : canonical;\n}\n\nasync function lstatOrNull(path: string) {\n  try {\n    return await fs.lstat(path);\n  } catch {\n    return null;\n  }\n}\n\n/** 名称只允许一个普通路径段；不把既有技能名称限制为 kebab-case。 */\nexport function entryPath(root: string, name: string) {\n  if (\n    typeof name !== \"string\" ||\n    name === \"\" ||\n    name === \".\" ||\n    name === \"..\" ||\n    name.startsWith(\".\") ||\n    name.length > MAX_ENTRY_NAME_LENGTH ||\n    /[\\\\/:*?\"<>|\\0]/.test(name) ||\n    /[. ]$/.test(name) ||\n    WINDOWS_DEVICE_NAME_RE.test(name) ||\n    basename(name) !== name\n  )\n    return null;\n  const rootPath = resolve(root);\n  const path = resolve(rootPath, name);\n  return isSameOrDescendant(rootPath, path) && rootPath !== path ? path : null;\n}\n\nfunction isDshRoot(root: RootInput) {\n  return typeof root === \"string\" && resolve(root) === resolve(dshRootPath());\n}\n\n// ── 命名规整 ────────────────────────────────────────────────────────────────\n\n/** 尽量把英文变体规整为 kebab-case；包含非 ASCII 字符或无法生成合法名称时返回空串。 */\nexport function toKebab(s: string) {\n  let t = String(s).trim();\n  if (t === \"\" || /[^\\x00-\\x7F]/.test(t)) return \"\";\n  t = t.replace(/([a-z0-9])([A-Z])/g, \"$1-$2\"); // camelCase 边界\n  t = t.toLowerCase();\n  t = t.replace(/[\\s_.]+/g, \"-\");\n  t = t.replace(/[^a-z0-9-]/g, \"-\");\n  t = t.replace(/-+/g, \"-\").replace(/^-+|-+$/g, \"\");\n  return t;\n}\n\n// ── frontmatter 解析 / 序列化（宽松 YAML 对象，保留键序）────────────────────\n\n/** 剥离 UTF-8 BOM（Windows 工具常写入，不剥离会导致开头 --- 失配）。 */\nfunction stripBom(text: string) {\n  return text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;\n}\n\n/** 解析 SKILL.md 的 frontmatter。返回 { fields, map, body }，map 保留键序。\n *  只识别顶层 key: value；缩进嵌套字段（如 metadata.source）不进入 map。 */\nexport function parseSkillDoc(text: string): ParsedSkill {\n  const src = stripBom(String(text));\n  const lines = src.split(/\\r?\\n/);\n  const map: Record<string, string> = Object.create(null);\n  const fields = [];\n  let body = src;\n  let hasFrontmatter = false;\n  if (lines.length > 0 && lines[0].trim() === \"---\") {\n    let end = -1;\n    for (let i = 1; i < lines.length; i++) {\n      if (lines[i].trim() === \"---\") {\n        end = i;\n        break;\n      }\n    }\n    if (end >= 0) {\n      hasFrontmatter = true;\n      for (let i = 1; i < end; i++) {\n        const m = /^([A-Za-z0-9_-]+)\\s*:\\s*(.*)$/.exec(lines[i]);\n        if (m) {\n          fields.push({ key: m[1], raw: m[2] });\n          const block = /^([>|])(?:([1-9])[-+]?|[-+]([1-9])?)?\\s*$/.exec(m[2]);\n          if (block) {\n            const content = [];\n            while (\n              i + 1 < end &&\n              (/^\\s/.test(lines[i + 1]) || lines[i + 1] === \"\")\n            ) {\n              i++;\n              content.push(lines[i]);\n            }\n            const explicitIndentation = block[2] || block[3];\n            const indentation = explicitIndentation\n              ? Number(explicitIndentation)\n              : content\n                  .filter((line) => line.trim() !== \"\")\n                  .reduce(\n                    (min, line) =>\n                      Math.min(min, (/^\\s*/.exec(line) || [\"\"])[0].length),\n                    Infinity,\n                  );\n            const normalized = content.map((line) =>\n              Number.isFinite(indentation)\n                ? line.slice(Math.min(indentation, line.length))\n                : line,\n            );\n            map[m[1]] =\n              block[1] === \">\"\n                ? normalized.join(\" \").replace(/\\s+/g, \" \").trim()\n                : explicitIndentation\n                  ? normalized.join(\"\\n\").replace(/^\\n+|\\n+$/g, \"\")\n                  : normalized.join(\"\\n\").trim();\n          } else {\n            map[m[1]] = decodeYamlScalar(m[2]);\n          }\n        }\n      }\n      body = lines.slice(end + 1).join(\"\\n\");\n    }\n  }\n  return { fields, map, body, hasFrontmatter };\n}\n\n/** 读取 YAML 标量的显示值；不依赖第三方 YAML 解析器。 */\nfunction decodeYamlScalar(v: string) {\n  const s = String(v == null ? \"\" : v).trim();\n  if (s.length >= 2 && s[0] === '\"' && s[s.length - 1] === '\"') {\n    try {\n      const value: unknown = JSON.parse(s);\n      if (typeof value === \"string\"